DECLARE
  task_row work.task%ROWTYPE;
  dedup_row work.submission_dedup%ROWTYPE;
  req_hash text;
  new_acceptance_id uuid := gen_random_uuid();
BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  PERFORM work.lock_request_key(p_org_id, p_subject_id, 'task.accept', p_client_request_id);
  IF (p_artifact_id IS NULL) = (p_completion_reason IS NULL)
     OR (p_artifact_id IS NOT NULL AND p_version_no IS NULL)
     OR (p_completion_reason IS NOT NULL AND char_length(btrim(p_completion_reason)) NOT BETWEEN 1 AND 500) THEN
    RAISE EXCEPTION 'acceptance_requires_artifact_or_reason' USING ERRCODE = '22023';
  END IF;
  req_hash := work.sha256_text(concat_ws(':', p_task_id, p_expected_revision, p_artifact_id, p_version_no,
                                         work.sha256_text(COALESCE(p_completion_reason, ''))));
  SELECT * INTO dedup_row
  FROM work.submission_dedup d
  WHERE d.org_id = p_org_id AND d.subject_id = p_subject_id
    AND d.operation_type = 'task.accept' AND d.client_request_id = p_client_request_id;
  IF FOUND THEN
    IF dedup_row.request_hash <> req_hash THEN
      RAISE EXCEPTION 'idempotency_key_conflict' USING ERRCODE = 'P0001';
    END IF;
    IF dedup_row.task_deleted THEN
      RAISE EXCEPTION 'task_not_found' USING ERRCODE = 'P0002';
    END IF;
    RETURN QUERY SELECT dedup_row.result_ref::uuid, (p_expected_revision + 1);
    RETURN;
  END IF;

  SELECT * INTO task_row
  FROM work.task t
  WHERE t.id = p_task_id AND t.org_id = p_org_id AND t.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND OR task_row.owner_subject_id <> p_subject_id THEN
    RAISE EXCEPTION 'task_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF task_row.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001', DETAIL = task_row.revision::text;
  END IF;
  IF task_row.state <> 'awaiting_acceptance' THEN
    RAISE EXCEPTION 'task_not_acceptable' USING ERRCODE = 'P0001';
  END IF;
  IF task_row.active_run_id IS NOT NULL OR work.task_has_blocking_operation(p_task_id, p_org_id) THEN
    RAISE EXCEPTION 'run_not_quiescent' USING ERRCODE = 'P0001';
  END IF;
  IF p_artifact_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM work.artifact a
    JOIN work.artifact_version v ON v.artifact_id = a.id AND v.org_id = a.org_id
    WHERE a.id = p_artifact_id AND a.org_id = p_org_id AND a.task_id = p_task_id
      AND a.deleted_at IS NULL AND v.version_no = p_version_no
      AND a.state = 'published' AND v.state = 'published'
  ) THEN
    RAISE EXCEPTION 'artifact_not_published' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.task t
  SET state = 'completed', revision = t.revision + 1, updated_at = now()
  WHERE t.id = p_task_id AND t.org_id = p_org_id;
  INSERT INTO work.acceptance
    (id, org_id, task_id, artifact_id, version_no, actor_subject_id, task_revision, completion_reason)
  VALUES
    (new_acceptance_id, p_org_id, p_task_id, p_artifact_id, p_version_no, p_subject_id,
     p_expected_revision + 1, btrim(p_completion_reason));
  INSERT INTO work.submission_dedup
    (org_id, subject_id, operation_type, client_request_id, request_hash, task_id, result_state, result_ref)
  VALUES
    (p_org_id, p_subject_id, 'task.accept', p_client_request_id, req_hash, p_task_id, 'completed',
     new_acceptance_id::text);
  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'task.accept', 'task', p_task_id::text,
    jsonb_build_object('acceptance_id', new_acceptance_id,
                       'basis', CASE WHEN p_artifact_id IS NULL THEN 'reason' ELSE 'version' END,
                       'artifact_id', p_artifact_id, 'version_no', p_version_no)
  );
  RETURN QUERY SELECT new_acceptance_id, task_row.revision + 1;
END;

DECLARE
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  v_task_id uuid;
BEGIN
  SELECT r.task_id INTO v_task_id
  FROM work.run r
  WHERE r.id = p_run_id AND r.org_id = p_org_id;
  IF v_task_id IS NULL THEN
    RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO task_row FROM work.task t WHERE t.id = v_task_id AND t.org_id = p_org_id FOR UPDATE;
  SELECT * INTO run_row FROM work.run r WHERE r.id = p_run_id AND r.org_id = p_org_id FOR UPDATE;
  -- 启动前已取消或已终态：原样返回，由工作流收尾，不 bump fence。
  IF run_row.state IN ('cancel_requested', 'succeeded', 'failed', 'canceled') THEN
    RETURN run_row;
  END IF;
  IF task_row.state <> 'open'
     OR task_row.active_run_id IS DISTINCT FROM p_run_id THEN
    RAISE EXCEPTION 'run_not_current' USING ERRCODE = 'P0001';
  END IF;
  IF run_row.state IN ('active', 'waiting') THEN
    RETURN run_row;
  END IF;
  IF run_row.state <> 'queued' THEN
    RAISE EXCEPTION 'run_not_queued' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.run r
  SET state = 'active',
      fence = r.fence + 1,
      control_revision = r.control_revision + 1,
      updated_at = now()
  WHERE r.id = p_run_id AND r.org_id = p_org_id
  RETURNING * INTO run_row;
  RETURN run_row;
END;

DECLARE
  reservation work.quota_reservation%ROWTYPE;
  existing_amount bigint;
BEGIN
  SELECT * INTO reservation FROM work.quota_reservation
    WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reservation_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF reservation.state <> 'settled' THEN
    RAISE EXCEPTION 'reservation_not_settled' USING ERRCODE = 'P0001';
  END IF;
  IF p_settlement_revision <= reservation.settlement_revision THEN
    SELECT amount_tokens INTO existing_amount
    FROM work.quota_entry
    WHERE operation_id = reservation.operation_id
      AND kind = 'adjust'
      AND settlement_revision = p_settlement_revision
    LIMIT 1;
    IF existing_amount IS NOT NULL AND existing_amount = p_delta_tokens THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'settlement_revision_not_monotonic' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.quota_account
    SET settled_tokens = settled_tokens + p_delta_tokens,
        version = version + 1,
        updated_at = now()
    WHERE id = reservation.account_id;
  UPDATE work.quota_reservation
    SET settlement_revision = p_settlement_revision
    WHERE id = reservation.id;
  INSERT INTO work.quota_entry
    (org_id, account_id, reservation_id, operation_id, kind, amount_tokens,
     settlement_revision, usage)
  VALUES
    (reservation.org_id, reservation.account_id, reservation.id, reservation.operation_id,
     'adjust', p_delta_tokens, p_settlement_revision,
     jsonb_build_object('reason', p_reason));
END;

DECLARE
  org_row work.org%ROWTYPE;
  account work.quota_account%ROWTYPE;
  policy_row work.org_policy%ROWTYPE;
  seat_total bigint;
  seat_active bigint;
BEGIN
  PERFORM work.assert_org_admin(p_org_id, p_subject_id);

  SELECT * INTO org_row FROM work.org o WHERE o.id = p_org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*) FILTER (WHERE m.status <> 'left'),
         count(*) FILTER (WHERE m.status = 'active' AND m.work_seat)
    INTO seat_total, seat_active
  FROM work.member m
  WHERE m.org_id = p_org_id;

  SELECT * INTO account
  FROM work.quota_account b
  WHERE b.org_id = p_org_id AND b.account_key = p_account_key AND b.period_id = p_period_id;

  SELECT * INTO policy_row FROM work.org_policy p WHERE p.org_id = p_org_id;

  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'admin.overview_read', 'org', p_org_id,
    jsonb_build_object('account_key', p_account_key, 'period_id', p_period_id)
  );

  RETURN jsonb_build_object(
    'org_id', org_row.id,
    'name', org_row.name,
    'status', org_row.status,
    'execution_enabled', org_row.execution_enabled AND NOT org_row.operator_suspended,
    'seats', jsonb_build_object('total', seat_total, 'active', seat_active),
    'quota', jsonb_build_object(
      'limit_tokens', COALESCE(account.limit_tokens, 0),
      'reserved_tokens', COALESCE(account.reserved_tokens, 0),
      'settled_tokens', COALESCE(account.settled_tokens, 0),
      'enforcement', COALESCE(account.enforcement, 'soft')
    ),
    'quota_period_id', p_period_id,
    'run_cap_tokens', COALESCE(policy_row.run_cap_tokens, 0),
    'org_revision', org_row.revision,
    'audit_retention_days',
      COALESCE(NULLIF(policy_row.policy->>'audit_retention_days', '')::int, 365)
  );
END;

DECLARE
  audit_id uuid := gen_random_uuid();
BEGIN
  INSERT INTO work.audit_event
    (id, org_id, actor_subject_id, action, target_type, target_id, metadata)
  VALUES
    (audit_id, p_org_id, p_actor_subject_id, p_action, p_target_type, p_target_id,
     COALESCE(p_metadata, '{}'::jsonb));
  RETURN audit_id;
END;

DECLARE
  next_seq bigint;
  event_id uuid := gen_random_uuid();
BEGIN
  PERFORM 1 FROM work.task
  WHERE id = p_task_id AND org_id = p_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'task_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT COALESCE(MAX(seq), 0) + 1 INTO next_seq
  FROM work.task_event
  WHERE task_id = p_task_id AND org_id = p_org_id;
  INSERT INTO work.task_event
    (id, org_id, task_id, seq, type, payload)
  VALUES
    (event_id, p_org_id, p_task_id, next_seq, p_type, COALESCE(p_payload, '{}'::jsonb));
  INSERT INTO work.outbox
    (org_id, aggregate_type, aggregate_id, event_id, payload)
  VALUES
    (p_org_id, 'task', p_task_id, event_id,
     COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('kind', 'task_event'));
  RETURN event_id;
END;

BEGIN
  IF NEW.artifact_id <> OLD.artifact_id
     OR NEW.org_id <> OLD.org_id
     OR NEW.version_no <> OLD.version_no
     OR NEW.content_ref <> OLD.content_ref
     OR NEW.content_hash <> OLD.content_hash
     OR NEW.bytes <> OLD.bytes
     OR NEW.media_type <> OLD.media_type
     OR NEW.provenance <> OLD.provenance THEN
    RAISE EXCEPTION 'artifact_version_content_immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF p_ref IS NULL OR length(btrim(p_ref)) = 0 OR length(p_ref) > 512 THEN
    RAISE EXCEPTION 'invalid_request:%', p_label USING ERRCODE = '22023';
  END IF;
END;

BEGIN
  IF p_hash IS NULL OR p_hash !~ '^sha256:[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid_request:%', p_label USING ERRCODE = '22023';
  END IF;
END;

BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  IF NOT EXISTS (
    SELECT 1 FROM work.member m
    WHERE m.org_id = p_org_id
      AND m.subject_id = p_subject_id
      AND m.status = 'active'
      AND m.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'admin_access_denied' USING ERRCODE = '42501';
  END IF;
END;

DECLARE
  org_row work.org%ROWTYPE;
BEGIN
  SELECT * INTO org_row FROM work.org o WHERE o.id = p_org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'org_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF org_row.status <> 'active' OR NOT org_row.execution_enabled OR org_row.operator_suspended THEN
    RAISE EXCEPTION 'org_execution_disabled' USING ERRCODE = 'P0001';
  END IF;
END;

BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  IF NOT EXISTS (
    SELECT 1 FROM work.member m
    WHERE m.org_id = p_org_id
      AND m.subject_id = p_subject_id
      AND m.status = 'active'
      AND m.role = 'owner'
  ) THEN
    RAISE EXCEPTION 'owner_access_denied' USING ERRCODE = '42501';
  END IF;
END;

BEGIN
  IF p_org_id IS NULL OR p_org_id = ''
     OR NULLIF(current_setting('app.org_id', true), '') IS NULL
     OR p_org_id IS DISTINCT FROM current_setting('app.org_id', true) THEN
    RAISE EXCEPTION 'runtime_org_context_mismatch' USING ERRCODE = '42501';
  END IF;
END;

BEGIN
  IF p_value IS NULL OR p_value !~ '^[A-Za-z0-9_.:@-]{1,128}$' THEN
    RAISE EXCEPTION 'invalid_request:%', p_label USING ERRCODE = '22023';
  END IF;
END;

BEGIN
  IF p_subject_id IS NULL OR p_subject_id = ''
     OR p_subject_id IS DISTINCT FROM nullif(current_setting('app.subject_id', true), '') THEN
    RAISE EXCEPTION 'actor_mismatch' USING ERRCODE = '42501';
  END IF;
END;

DECLARE
  gate_row work.dispatch_delivery%ROWTYPE;
  v_run_id uuid;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  PERFORM work.assert_content_ref('receipt_ref', p_receipt_ref);
  PERFORM work.assert_document_hash('receipt_hash', p_receipt_hash);
  IF p_receipt_result IS NULL OR p_receipt_result NOT IN ('success', 'rejected_not_executed') THEN
    RAISE EXCEPTION 'invalid_request:receipt_result' USING ERRCODE = '22023';
  END IF;
  IF p_receipt_slot_id IS NULL THEN
    RAISE EXCEPTION 'invalid_request:receipt_slot_id' USING ERRCODE = '22023';
  END IF;
  SELECT o.run_id INTO v_run_id
  FROM work.operation o
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF v_run_id IS NULL THEN
    RAISE EXCEPTION 'operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM work.lock_runtime_run(p_org_id, v_run_id);
  SELECT * INTO gate_row
  FROM work.dispatch_delivery d
  WHERE d.org_id = p_org_id AND d.operation_id = p_operation_id
  FOR UPDATE;
  IF gate_row.operation_id IS NULL THEN
    RAISE EXCEPTION 'dispatch_gate_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF gate_row.gate_state = 'sealed_not_sent' THEN
    RAISE EXCEPTION 'dispatch_gate_sealed_not_sent' USING ERRCODE = 'P0001';
  END IF;
  IF gate_row.receipt_slot_id IS DISTINCT FROM p_receipt_slot_id THEN
    RAISE EXCEPTION 'receipt_slot_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF gate_row.gate_state = 'receipt_recorded' THEN
    IF gate_row.receipt_hash = p_receipt_hash
       AND gate_row.receipt_ref = p_receipt_ref
       AND gate_row.receipt_result = p_receipt_result THEN
      RETURN jsonb_build_object(
        'outcome', 'idempotent',
        'gate_state', gate_row.gate_state,
        'receipt_hash', gate_row.receipt_hash
      );
    END IF;
    RAISE EXCEPTION 'receipt_content_conflict' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.dispatch_delivery d
  SET gate_state = 'receipt_recorded',
      receipt_ref = p_receipt_ref,
      receipt_hash = p_receipt_hash,
      receipt_result = p_receipt_result,
      provider_request_id = p_provider_request_id,
      gateway_invocation_id = COALESCE(p_gateway_invocation_id, d.gateway_invocation_id),
      receipt_recorded_at = now(),
      revision = d.revision + 1,
      updated_at = now()
  WHERE d.org_id = p_org_id AND d.operation_id = p_operation_id;
  PERFORM work.append_audit(
    p_org_id, NULL, 'dispatch.receipt_attached', 'operation', p_operation_id::text,
    jsonb_build_object(
      'receipt_slot_id', p_receipt_slot_id, 'receipt_hash', p_receipt_hash,
      'receipt_result', p_receipt_result, 'provider_request_id', p_provider_request_id
    )
  );
  RETURN jsonb_build_object(
    'outcome', 'recorded',
    'gate_state', 'receipt_recorded',
    'receipt_hash', p_receipt_hash
  );
END;

DECLARE
  task_id uuid;
  operation_row work.operation%ROWTYPE;
BEGIN
  IF p_decision_source <> 'policy_auto' THEN
    RAISE EXCEPTION 'invalid_decision_source' USING ERRCODE = '22023';
  END IF;
  IF p_policy_epoch IS NULL OR p_policy_epoch <= 0 THEN
    RAISE EXCEPTION 'invalid_policy_epoch' USING ERRCODE = '22023';
  END IF;
  SELECT r.task_id INTO task_id
  FROM work.operation o
  JOIN work.run r ON r.id = o.run_id AND r.org_id = o.org_id
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF task_id IS NULL THEN
    RAISE EXCEPTION 'operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM work.task WHERE id = task_id AND org_id = p_org_id FOR UPDATE;
  SELECT * INTO operation_row
  FROM work.operation
  WHERE id = p_operation_id AND org_id = p_org_id
  FOR UPDATE;
  IF operation_row.state = 'waiting_approval' THEN
    RAISE EXCEPTION 'approval_required' USING ERRCODE = 'P0001';
  END IF;
  IF operation_row.state <> 'prepared' THEN
    RAISE EXCEPTION 'operation_not_authorizable' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.operation
  SET state = 'authorized',
      revision = revision + 1,
      updated_at = now()
  WHERE id = p_operation_id AND org_id = p_org_id;
  PERFORM work.append_task_event(
    p_org_id, task_id, 'operation.authorized',
    jsonb_build_object(
      'operation_id', p_operation_id,
      'decision_source', p_decision_source,
      'policy_epoch', p_policy_epoch
    )
  );
  PERFORM work.append_audit(
    p_org_id, NULL, 'operation.authorize', 'operation', p_operation_id::text,
    jsonb_build_object('policy_epoch', p_policy_epoch, 'decision_source', p_decision_source)
  );
END;

DECLARE
  capability_row work.runtime_capability%ROWTYPE;
  execution_row work.runtime_execution%ROWTYPE;
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  v_now timestamptz;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  -- Malformed bearer metadata is simply not authorized.
  IF p_execution_id IS NULL OR p_audience IS NULL
     OR p_audience NOT IN ('work-content', 'work-egress')
     OR p_generation IS NULL OR p_generation < 1
     OR p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN
    RETURN false;
  END IF;

  SELECT * INTO capability_row
  FROM work.runtime_capability c
  WHERE c.org_id = p_org_id AND c.execution_id = p_execution_id
    AND c.audience = p_audience AND c.generation = p_generation
    AND c.token_hash = p_token_hash;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  v_now := clock_timestamp();
  IF capability_row.revoked_at IS NOT NULL OR capability_row.expires_at <= v_now THEN
    RETURN false;
  END IF;
  -- Only the current generation authorizes; a superseded generation is kept
  -- for audit but is dead from the moment the next one commits.
  IF EXISTS (
    SELECT 1 FROM work.runtime_capability c
    WHERE c.org_id = p_org_id AND c.execution_id = p_execution_id
      AND c.audience = p_audience AND c.generation > p_generation
  ) THEN
    RETURN false;
  END IF;

  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF execution_row.state <> 'active'
     OR execution_row.holder_id IS DISTINCT FROM capability_row.holder_id
     OR execution_row.lease_until <= v_now
     OR execution_row.hard_deadline <= v_now THEN
    RETURN false;
  END IF;
  -- Mode narrowing is re-checked online: a plan fragment may only present the
  -- content audience, an execute fragment only the model egress audience.
  IF (execution_row.mode = 'plan' AND p_audience <> 'work-content')
     OR (execution_row.mode = 'execute' AND p_audience <> 'work-egress') THEN
    RETURN false;
  END IF;
  SELECT * INTO run_row
  FROM work.run r
  WHERE r.id = execution_row.run_id AND r.org_id = p_org_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  SELECT * INTO task_row
  FROM work.task t
  WHERE t.id = run_row.task_id AND t.org_id = p_org_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF task_row.state <> 'open' OR task_row.active_run_id IS DISTINCT FROM run_row.id
     OR run_row.state <> 'active' OR run_row.fence <> execution_row.run_fence THEN
    RETURN false;
  END IF;
  -- A suspended or execution-disabled organization fails closed.
  IF NOT EXISTS (
    SELECT 1 FROM work.org o
    WHERE o.id = p_org_id AND o.status = 'active'
      AND o.execution_enabled AND NOT o.operator_suspended
  ) THEN
    RETURN false;
  END IF;
  RETURN true;
END;

DECLARE
  task_id uuid;
  operation_row work.operation%ROWTYPE;
  reservation_id uuid;
  reason text := work.reason_code(p_reason);
BEGIN
  SELECT r.task_id INTO task_id
  FROM work.operation o
  JOIN work.run r ON r.id = o.run_id AND r.org_id = o.org_id
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF task_id IS NULL THEN
    RAISE EXCEPTION 'operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM work.task t WHERE t.id = task_id AND t.org_id = p_org_id FOR UPDATE;
  SELECT * INTO operation_row
  FROM work.operation o
  WHERE o.id = p_operation_id AND o.org_id = p_org_id
  FOR UPDATE;
  IF operation_row.state IN ('succeeded', 'failed', 'canceled', 'reconciled', 'unresolved', 'unknown') THEN
    RETURN;
  END IF;
  IF operation_row.state = 'dispatching' THEN
    UPDATE work.operation o
    SET state = 'unknown',
        revision = o.revision + 1,
        updated_at = now()
    WHERE o.id = p_operation_id AND o.org_id = p_org_id;
    PERFORM work.append_task_event(
      p_org_id, task_id, 'operation.unknown',
      jsonb_build_object('operation_id', p_operation_id, 'reason', reason)
    );
    PERFORM work.append_audit(
      p_org_id, p_actor_subject_id, 'operation.unknown', 'operation', p_operation_id::text,
      jsonb_build_object('reason', reason)
    );
    RETURN;
  END IF;
  UPDATE work.operation o
  SET state = 'canceled',
      revision = o.revision + 1,
      updated_at = now()
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  UPDATE work.approval a
  SET status = 'expired', revision = a.revision + 1, updated_at = now()
  FROM work.approval_operation ao
  WHERE ao.approval_id = a.id AND ao.org_id = a.org_id
    AND ao.operation_id = p_operation_id AND a.org_id = p_org_id
    AND a.status = 'pending';
  SELECT br.id INTO reservation_id
  FROM work.quota_reservation br
  WHERE br.operation_id = p_operation_id AND br.state = 'held';
  IF reservation_id IS NOT NULL THEN
    PERFORM work.release_quota(reservation_id);
  END IF;
  PERFORM work.append_task_event(
    p_org_id, task_id, 'operation.canceled',
    jsonb_build_object('operation_id', p_operation_id, 'reason', reason)
  );
  PERFORM work.append_audit(
    p_org_id, p_actor_subject_id, 'operation.cancel', 'operation', p_operation_id::text,
    jsonb_build_object('reason', reason)
  );
END;

DECLARE
  export_row work.audit_export%ROWTYPE;
BEGIN
  IF p_worker_id IS NULL OR p_worker_id = '' THEN
    RAISE EXCEPTION 'invalid_request:worker_id' USING ERRCODE = '22023';
  END IF;
  IF p_lease_seconds IS NULL OR p_lease_seconds < 30 OR p_lease_seconds > 3600 THEN
    RAISE EXCEPTION 'invalid_request:lease_seconds' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO export_row
  FROM work.audit_export e
  WHERE e.id = p_export_id AND e.org_id = current_setting('app.org_id', true)
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit_export_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF export_row.status = 'running' AND export_row.lease_until > now() THEN
    RAISE EXCEPTION 'audit_export_not_claimable' USING ERRCODE = 'P0001';
  END IF;
  IF export_row.status NOT IN ('queued', 'running') THEN
    RAISE EXCEPTION 'audit_export_not_claimable' USING ERRCODE = 'P0001';
  END IF;

  UPDATE work.audit_export e
    SET status = 'running',
        lease_owner = p_worker_id,
        lease_until = now() + make_interval(secs => p_lease_seconds),
        error_code = NULL,
        updated_at = now()
  WHERE e.id = export_row.id
  RETURNING * INTO export_row;

  PERFORM work.append_audit(
    export_row.org_id, NULL, 'audit_export.claimed', 'audit_export', export_row.id::text,
    jsonb_build_object('worker_id', p_worker_id)
  );
  RETURN work.audit_export_view(export_row);
END;

DECLARE
  operation_row work.operation%ROWTYPE;
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  attempt uuid := gen_random_uuid();
BEGIN
  SELECT * INTO operation_row FROM work.operation o WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT * INTO run_row FROM work.run r WHERE r.id = operation_row.run_id AND r.org_id = p_org_id;
  SELECT * INTO task_row FROM work.task t WHERE t.id = run_row.task_id AND t.org_id = p_org_id FOR UPDATE;
  SELECT * INTO run_row FROM work.run r WHERE r.id = operation_row.run_id AND r.org_id = p_org_id FOR UPDATE;
  SELECT * INTO operation_row FROM work.operation o WHERE o.id = p_operation_id AND o.org_id = p_org_id FOR UPDATE;
  IF operation_row.state = 'dispatching'
     AND operation_row.consumer_id = p_consumer_id
     AND run_row.fence = p_fence THEN
    RETURN operation_row.dispatch_attempt_id;
  END IF;
  IF task_row.state <> 'open'
     OR task_row.active_run_id IS DISTINCT FROM run_row.id
     OR run_row.state <> 'active'
     OR run_row.fence <> p_fence
     OR operation_row.state <> 'authorized'
     OR operation_row.dispatch_attempt_id IS NOT NULL THEN
    RETURN NULL;
  END IF;
  UPDATE work.operation o
  SET state = 'dispatching',
      dispatch_attempt_id = attempt,
      consumer_id = p_consumer_id,
      revision = o.revision + 1,
      updated_at = now()
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  RETURN attempt;
END;

DECLARE
  execution_row work.runtime_execution%ROWTYPE;
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  v_now timestamptz;
  v_lease timestamptz;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  PERFORM work.assert_runtime_identifier('holder_id', p_holder_id);
  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'runtime_execution_not_found' USING ERRCODE = 'P0002';
  END IF;
  run_row := work.lock_runtime_run(p_org_id, execution_row.run_id);
  SELECT * INTO task_row FROM work.task t WHERE t.id = run_row.task_id AND t.org_id = p_org_id;
  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id
  FOR UPDATE;
  v_now := clock_timestamp();

  IF execution_row.state IN ('completed', 'revoked', 'expired') THEN
    RAISE EXCEPTION 'runtime_execution_not_claimable' USING ERRCODE = 'P0001',
      DETAIL = execution_row.state;
  END IF;
  IF execution_row.hard_deadline <= v_now
     OR (execution_row.state = 'active' AND execution_row.lease_until <= v_now) THEN
    -- Refuse only: the elapsed row stays until register_runtime_execution
    -- commits the explicit expiry and replaces it.
    RAISE EXCEPTION 'runtime_execution_expired' USING ERRCODE = 'P0001';
  END IF;
  IF execution_row.state = 'active' THEN
    IF execution_row.holder_id IS DISTINCT FROM p_holder_id THEN
      RAISE EXCEPTION 'runtime_execution_holder_mismatch' USING ERRCODE = '42501';
    END IF;
    -- Same holder: state query only, never a second fork.
    RETURN 'already_claimed';
  END IF;

  PERFORM work.assert_org_execution_enabled(p_org_id);
  IF task_row.state <> 'open' OR task_row.active_run_id IS DISTINCT FROM run_row.id
     OR run_row.state <> 'active' OR run_row.fence <> execution_row.run_fence THEN
    RAISE EXCEPTION 'run_not_current' USING ERRCODE = 'P0001';
  END IF;
  v_lease := LEAST(v_now + make_interval(secs => work.runtime_lease_seconds()),
                   execution_row.hard_deadline);
  UPDATE work.runtime_execution e
  SET state = 'active', holder_id = p_holder_id, lease_until = v_lease,
      revision = e.revision + 1, updated_at = now()
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id;
  PERFORM work.append_audit(
    p_org_id, NULL, 'runtime.execution_claimed', 'runtime_execution', p_execution_id::text,
    jsonb_build_object('holder_id', p_holder_id, 'lease_until', v_lease)
  );
  RETURN 'claimed';
END;

DECLARE
  reference_row work.content_reference%ROWTYPE;
  v_task_id uuid;
  v_run_id uuid;
  v_updated integer;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  IF p_ref_id IS NULL THEN
    RAISE EXCEPTION 'invalid_request:ref_id' USING ERRCODE = '22023';
  END IF;
  PERFORM work.assert_content_ref('content_ref', p_content_ref);
  PERFORM work.assert_document_hash('content_hash', p_content_hash);
  IF p_bytes IS NULL OR p_bytes < 0 THEN
    RAISE EXCEPTION 'invalid_request:bytes' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO reference_row
  FROM work.content_reference cr
  WHERE cr.org_id = p_org_id AND cr.ref_id = p_ref_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'content_reference_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF reference_row.tombstoned_at IS NOT NULL THEN
    RAISE EXCEPTION 'content_slot_conflict' USING ERRCODE = 'P0001',
      DETAIL = 'tombstoned';
  END IF;
  IF reference_row.writer_kind <> 'runtime_child' THEN
    RAISE EXCEPTION 'content_reference_writer_not_allowed' USING ERRCODE = 'P0001';
  END IF;

  IF reference_row.slot_state = 'committed' THEN
    IF reference_row.content_ref = p_content_ref
       AND reference_row.content_hash = p_content_hash
       AND reference_row.bytes = p_bytes THEN
      PERFORM work.append_audit(
        p_org_id, NULL, 'content.reference_committed', 'content_reference',
        p_ref_id::text,
        jsonb_build_object(
          'outcome', 'idempotent', 'kind', reference_row.kind,
          'logical_slot', reference_row.logical_slot,
          'execution_id', reference_row.execution_id
        )
      );
      RETURN jsonb_build_object(
        'outcome', 'idempotent', 'ref_id', p_ref_id,
        'slot_state', 'committed'
      );
    END IF;
    RAISE EXCEPTION 'content_slot_conflict' USING ERRCODE = 'P0001';
  END IF;

  -- The reservation is only valid while the execution still binds the same
  -- tenant/task/run. A terminal execution may still finish an in-flight
  -- candidate commit; head promotion is a separate command.
  SELECT e.task_id, e.run_id
    INTO v_task_id, v_run_id
  FROM work.runtime_execution e
  WHERE e.execution_id = reference_row.execution_id AND e.org_id = p_org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'runtime_execution_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_task_id IS DISTINCT FROM reference_row.task_id
     OR v_run_id IS DISTINCT FROM reference_row.run_id THEN
    RAISE EXCEPTION 'content_reference_binding_mismatch' USING ERRCODE = 'P0001';
  END IF;

  UPDATE work.content_reference
  SET content_ref = p_content_ref,
      content_hash = p_content_hash,
      bytes = p_bytes,
      slot_state = 'committed',
      updated_at = now()
  WHERE org_id = p_org_id
    AND ref_id = p_ref_id
    AND slot_state = 'reserved'
    AND tombstoned_at IS NULL;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RAISE EXCEPTION 'content_slot_conflict' USING ERRCODE = 'P0001';
  END IF;

  PERFORM work.append_audit(
    p_org_id, NULL, 'content.reference_committed', 'content_reference',
    p_ref_id::text,
    jsonb_build_object(
      'outcome', 'committed', 'kind', reference_row.kind,
      'logical_slot', reference_row.logical_slot,
      'execution_id', reference_row.execution_id
    )
  );
  RETURN jsonb_build_object(
    'outcome', 'committed', 'ref_id', p_ref_id, 'slot_state', 'committed'
  );
END;

DECLARE
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  execution_row work.runtime_execution%ROWTYPE;
  head_row work.runtime_checkpoint_head%ROWTYPE;
  v_now timestamptz;
  v_revision bigint;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  PERFORM work.assert_content_ref('checkpoint_ref', p_checkpoint_ref);
  PERFORM work.assert_document_hash('checkpoint_hash', p_checkpoint_hash);
  PERFORM work.assert_runtime_identifier('runtime_version', p_runtime_version);
  IF (p_expected_ref IS NULL) <> (p_expected_hash IS NULL)
     OR (p_expected_revision IS NULL) <> (p_expected_hash IS NULL) THEN
    RAISE EXCEPTION 'invalid_request:expected_base' USING ERRCODE = '22023';
  END IF;
  IF p_expected_revision IS NOT NULL AND p_expected_revision < 0 THEN
    RAISE EXCEPTION 'invalid_request:expected_revision' USING ERRCODE = '22023';
  END IF;

  run_row := work.lock_runtime_run(p_org_id, p_run_id);
  SELECT * INTO task_row FROM work.task t WHERE t.id = run_row.task_id AND t.org_id = p_org_id;
  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id
  FOR UPDATE;
  IF execution_row.execution_id IS NULL OR execution_row.run_id IS DISTINCT FROM p_run_id THEN
    RAISE EXCEPTION 'runtime_execution_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO head_row
  FROM work.runtime_checkpoint_head h
  WHERE h.org_id = p_org_id AND h.run_id = p_run_id
  FOR UPDATE;
  v_now := clock_timestamp();

  -- Replay of an already committed candidate: historical answer, no overwrite.
  IF head_row.run_id IS NOT NULL
     AND head_row.committed_execution_id = p_execution_id
     AND head_row.checkpoint_hash = p_checkpoint_hash
     AND head_row.checkpoint_ref = p_checkpoint_ref THEN
    RETURN head_row.checkpoint_revision;
  END IF;

  IF execution_row.state IN ('revoked', 'expired') THEN
    RAISE EXCEPTION 'runtime_execution_revoked' USING ERRCODE = 'P0001',
      DETAIL = execution_row.state;
  END IF;
  IF execution_row.state <> 'active' THEN
    RAISE EXCEPTION 'runtime_execution_not_active' USING ERRCODE = 'P0001',
      DETAIL = execution_row.state;
  END IF;
  IF execution_row.lease_until <= v_now OR execution_row.hard_deadline <= v_now THEN
    -- Refuse only; the expiry is committed by renew/register.
    RAISE EXCEPTION 'runtime_execution_expired' USING ERRCODE = 'P0001';
  END IF;
  IF task_row.state <> 'open' OR task_row.active_run_id IS DISTINCT FROM run_row.id
     OR run_row.state <> 'active' OR run_row.fence <> execution_row.run_fence THEN
    RAISE EXCEPTION 'run_not_current' USING ERRCODE = 'P0001';
  END IF;
  IF execution_row.input_checkpoint_hash IS DISTINCT FROM p_expected_hash
     OR execution_row.input_checkpoint_ref IS DISTINCT FROM p_expected_ref THEN
    RAISE EXCEPTION 'runtime_checkpoint_base_mismatch' USING ERRCODE = 'P0001';
  END IF;

  IF head_row.run_id IS NULL THEN
    IF p_expected_revision IS NOT NULL THEN
      RAISE EXCEPTION 'runtime_checkpoint_head_missing' USING ERRCODE = 'P0001';
    END IF;
    INSERT INTO work.runtime_checkpoint_head
      (org_id, run_id, task_id, checkpoint_revision, checkpoint_ref, checkpoint_hash,
       runtime_version, committed_execution_id)
    VALUES
      (p_org_id, p_run_id, run_row.task_id, 0, p_checkpoint_ref, p_checkpoint_hash,
       p_runtime_version, p_execution_id);
    v_revision := 0;
  ELSE
    IF p_expected_revision IS NULL
       OR head_row.checkpoint_revision <> p_expected_revision
       OR head_row.checkpoint_ref <> p_expected_ref
       OR head_row.checkpoint_hash <> p_expected_hash THEN
      RAISE EXCEPTION 'runtime_checkpoint_cas_conflict' USING ERRCODE = 'P0001',
        DETAIL = head_row.checkpoint_revision::text;
    END IF;
    v_revision := head_row.checkpoint_revision + 1;
    UPDATE work.runtime_checkpoint_head h
    SET checkpoint_revision = v_revision,
        checkpoint_ref = p_checkpoint_ref,
        checkpoint_hash = p_checkpoint_hash,
        runtime_version = p_runtime_version,
        committed_execution_id = p_execution_id,
        updated_at = now()
    WHERE h.org_id = p_org_id AND h.run_id = p_run_id;
  END IF;

  UPDATE work.runtime_execution e
  SET state = 'completed', lease_until = NULL, terminal_reason = 'checkpoint_committed',
      revision = e.revision + 1, updated_at = now()
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id;
  PERFORM work.append_audit(
    p_org_id, NULL, 'runtime.checkpoint_committed', 'run', p_run_id::text,
    jsonb_build_object(
      'execution_id', p_execution_id, 'checkpoint_revision', v_revision::text,
      'checkpoint_hash', p_checkpoint_hash, 'expected_revision',
      CASE WHEN p_expected_revision IS NULL THEN NULL ELSE p_expected_revision::text END
    )
  );
  RETURN v_revision;
END;

DECLARE
  export_row work.audit_export%ROWTYPE;
BEGIN
  IF p_content_ref IS NULL OR p_content_ref !~ '^content://' THEN
    RAISE EXCEPTION 'invalid_request:content_ref' USING ERRCODE = '22023';
  END IF;
  IF p_content_hash IS NULL OR p_content_hash !~ '^sha256:[0-9a-f]{8,}$' THEN
    RAISE EXCEPTION 'invalid_request:content_hash' USING ERRCODE = '22023';
  END IF;
  IF p_bytes IS NULL OR p_bytes < 0 OR p_row_count IS NULL OR p_row_count < 0 THEN
    RAISE EXCEPTION 'invalid_request:export_size' USING ERRCODE = '22023';
  END IF;
  IF p_ttl_seconds IS NULL OR p_ttl_seconds < 300 OR p_ttl_seconds > 604800 THEN
    RAISE EXCEPTION 'invalid_request:ttl_seconds' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO export_row
  FROM work.audit_export e
  WHERE e.id = p_export_id AND e.org_id = current_setting('app.org_id', true)
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit_export_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF export_row.status <> 'running'
     OR export_row.lease_owner IS DISTINCT FROM p_worker_id
     OR export_row.lease_until <= now() THEN
    RAISE EXCEPTION 'audit_export_lease_lost' USING ERRCODE = 'P0001';
  END IF;

  UPDATE work.audit_export e
    SET status = 'ready',
        content_ref = p_content_ref,
        content_hash = p_content_hash,
        bytes = p_bytes,
        row_count = p_row_count,
        ready_at = now(),
        expires_at = now() + make_interval(secs => p_ttl_seconds),
        lease_owner = NULL,
        lease_until = NULL,
        updated_at = now()
  WHERE e.id = export_row.id
  RETURNING * INTO export_row;

  PERFORM work.append_audit(
    export_row.org_id, NULL, 'audit_export.completed', 'audit_export', export_row.id::text,
    jsonb_build_object('row_count', p_row_count, 'bytes', p_bytes, 'content_hash', p_content_hash)
  );
  RETURN work.audit_export_view(export_row);
END;

DECLARE
  execution_row work.runtime_execution%ROWTYPE;
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  v_run_id uuid;
  v_now timestamptz;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  PERFORM work.assert_runtime_identifier('gateway_invocation_id', p_gateway_invocation_id);
  IF p_execution_id IS NULL OR p_request_hash IS NULL OR p_receipt_slot_id IS NULL THEN
    RAISE EXCEPTION 'invalid_request:consume_binding' USING ERRCODE = '22023';
  END IF;

  SELECT e.run_id INTO v_run_id
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id;
  IF v_run_id IS NULL THEN
    RAISE EXCEPTION 'runtime_execution_not_found' USING ERRCODE = 'P0002';
  END IF;

  run_row := work.lock_runtime_run(p_org_id, v_run_id);
  SELECT * INTO task_row FROM work.task t WHERE t.id = run_row.task_id AND t.org_id = p_org_id;
  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id
  FOR UPDATE;
  v_now := clock_timestamp();

  IF execution_row.state <> 'active' THEN
    RAISE EXCEPTION 'runtime_execution_not_active' USING ERRCODE = 'P0001',
      DETAIL = execution_row.state;
  END IF;
  IF execution_row.lease_until <= v_now OR execution_row.hard_deadline <= v_now THEN
    -- Refuse only; the expiry is committed by renew/register.
    RAISE EXCEPTION 'runtime_execution_expired' USING ERRCODE = 'P0001';
  END IF;
  IF task_row.state <> 'open' OR task_row.active_run_id IS DISTINCT FROM run_row.id
     OR run_row.state <> 'active' OR run_row.fence <> execution_row.run_fence THEN
    RAISE EXCEPTION 'run_not_current' USING ERRCODE = 'P0001';
  END IF;
  IF execution_row.mode <> 'execute'
     OR execution_row.operation_id IS NULL
     OR execution_row.dispatch_attempt_id IS NULL
     OR execution_row.request_hash IS NULL THEN
    RAISE EXCEPTION 'runtime_execution_intent_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF execution_row.request_hash IS DISTINCT FROM p_request_hash THEN
    RAISE EXCEPTION 'runtime_request_hash_mismatch' USING ERRCODE = 'P0001';
  END IF;

  -- Same gate function as the full-wire path: the derived binding is locked
  -- and validated there, and only its single successful inserter gets won.
  RETURN work.consume_dispatch_delivery(
    p_org_id,
    execution_row.operation_id,
    p_execution_id,
    execution_row.holder_id,
    execution_row.dispatch_attempt_id,
    p_request_hash,
    execution_row.run_fence,
    p_gateway_invocation_id,
    p_receipt_slot_id
  );
END;

DECLARE
  operation_row work.operation%ROWTYPE;
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  execution_row work.runtime_execution%ROWTYPE;
  gate_row work.dispatch_delivery%ROWTYPE;
  v_run_id uuid;
  v_now timestamptz;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  PERFORM work.assert_runtime_identifier('holder_id', p_holder_id);
  PERFORM work.assert_runtime_identifier('gateway_invocation_id', p_gateway_invocation_id);
  IF p_operation_id IS NULL OR p_execution_id IS NULL OR p_attempt_id IS NULL
     OR p_receipt_slot_id IS NULL OR p_request_hash IS NULL THEN
    RAISE EXCEPTION 'invalid_request:consume_binding' USING ERRCODE = '22023';
  END IF;
  IF p_run_fence IS NULL OR p_run_fence <= 0 THEN
    RAISE EXCEPTION 'invalid_request:run_fence' USING ERRCODE = '22023';
  END IF;

  SELECT o.run_id INTO v_run_id
  FROM work.operation o
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF v_run_id IS NULL THEN
    RAISE EXCEPTION 'operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  run_row := work.lock_runtime_run(p_org_id, v_run_id);
  SELECT * INTO task_row FROM work.task t WHERE t.id = run_row.task_id AND t.org_id = p_org_id;
  SELECT * INTO operation_row
  FROM work.operation o
  WHERE o.id = p_operation_id AND o.org_id = p_org_id
  FOR UPDATE;
  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id
  FOR UPDATE;
  SELECT * INTO gate_row
  FROM work.dispatch_delivery d
  WHERE d.org_id = p_org_id AND d.operation_id = p_operation_id
  FOR UPDATE;
  v_now := clock_timestamp();

  -- A gate that already exists ends the decision: observed, never won again.
  IF gate_row.operation_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'outcome', 'observed',
      'gate_state', gate_row.gate_state,
      'receipt_slot_id', gate_row.receipt_slot_id,
      'gateway_invocation_id', gate_row.gateway_invocation_id
    );
  END IF;

  IF execution_row.execution_id IS NULL THEN
    RAISE EXCEPTION 'runtime_execution_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF execution_row.state <> 'active' THEN
    RAISE EXCEPTION 'runtime_execution_not_active' USING ERRCODE = 'P0001',
      DETAIL = execution_row.state;
  END IF;
  IF execution_row.holder_id IS DISTINCT FROM p_holder_id THEN
    RAISE EXCEPTION 'runtime_execution_holder_mismatch' USING ERRCODE = '42501';
  END IF;
  IF execution_row.lease_until <= v_now OR execution_row.hard_deadline <= v_now THEN
    -- Refuse only; the expiry is committed by renew/register.
    RAISE EXCEPTION 'runtime_execution_expired' USING ERRCODE = 'P0001';
  END IF;
  IF execution_row.mode <> 'execute'
     OR execution_row.run_id IS DISTINCT FROM v_run_id
     OR execution_row.run_fence IS DISTINCT FROM p_run_fence
     OR execution_row.operation_id IS DISTINCT FROM p_operation_id
     OR execution_row.dispatch_attempt_id IS DISTINCT FROM p_attempt_id
     OR execution_row.request_hash IS DISTINCT FROM p_request_hash THEN
    RAISE EXCEPTION 'runtime_execution_intent_mismatch' USING ERRCODE = 'P0001';
  END IF;

  PERFORM work.assert_org_execution_enabled(p_org_id);
  IF task_row.state <> 'open' OR task_row.active_run_id IS DISTINCT FROM run_row.id
     OR run_row.state <> 'active' OR run_row.fence <> p_run_fence THEN
    RAISE EXCEPTION 'run_not_current' USING ERRCODE = 'P0001';
  END IF;
  IF operation_row.state <> 'dispatching'
     OR operation_row.dispatch_attempt_id IS DISTINCT FROM p_attempt_id
     OR operation_row.request_hash IS DISTINCT FROM p_request_hash THEN
    RAISE EXCEPTION 'operation_not_dispatchable' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM work.quota_reservation br
    WHERE br.org_id = p_org_id AND br.operation_id = p_operation_id
      AND br.state IN ('held', 'unknown')
  ) THEN
    RAISE EXCEPTION 'operation_reservation_missing' USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    INSERT INTO work.dispatch_delivery
      (org_id, operation_id, gate_state, execution_id, holder_id, attempt_id,
       request_hash, gateway_invocation_id, receipt_slot_id, consumed_at)
    VALUES
      (p_org_id, p_operation_id, 'consumed', p_execution_id, p_holder_id, p_attempt_id,
       p_request_hash, p_gateway_invocation_id, p_receipt_slot_id, v_now);
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO gate_row
    FROM work.dispatch_delivery d
    WHERE d.org_id = p_org_id AND d.operation_id = p_operation_id;
    RETURN jsonb_build_object(
      'outcome', 'observed',
      'gate_state', COALESCE(gate_row.gate_state, 'receipt_slot_taken'),
      'receipt_slot_id', gate_row.receipt_slot_id,
      'gateway_invocation_id', gate_row.gateway_invocation_id
    );
  END;
  PERFORM work.append_audit(
    p_org_id, NULL, 'dispatch.gate_consumed', 'operation', p_operation_id::text,
    jsonb_build_object(
      'execution_id', p_execution_id, 'holder_id', p_holder_id,
      'attempt_id', p_attempt_id, 'gateway_invocation_id', p_gateway_invocation_id,
      'receipt_slot_id', p_receipt_slot_id
    )
  );
  RETURN jsonb_build_object(
    'outcome', 'won',
    'gate_state', 'consumed',
    'receipt_slot_id', p_receipt_slot_id,
    'gateway_invocation_id', p_gateway_invocation_id
  );
END;

BEGIN
  IF NEW.ref_id IS DISTINCT FROM OLD.ref_id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.task_id IS DISTINCT FROM OLD.task_id
     OR NEW.run_id IS DISTINCT FROM OLD.run_id
     OR NEW.execution_id IS DISTINCT FROM OLD.execution_id
     OR NEW.kind IS DISTINCT FROM OLD.kind
     OR NEW.logical_slot IS DISTINCT FROM OLD.logical_slot
     OR NEW.object_version IS DISTINCT FROM OLD.object_version
     OR NEW.writer_kind IS DISTINCT FROM OLD.writer_kind
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'content_reference_binding_immutable' USING ERRCODE = '23514';
  END IF;
  IF OLD.tombstoned_at IS NOT NULL THEN
    -- A tombstoned row is final. It cannot be un-tombstoned, re-tombstoned or
    -- touched again; the audit trail is the only record of later calls.
    RAISE EXCEPTION 'content_reference_tombstone_immutable' USING ERRCODE = '23514';
  END IF;
  IF OLD.slot_state = 'committed' THEN
    IF NEW.slot_state IS DISTINCT FROM 'committed'
       OR NEW.content_ref IS DISTINCT FROM OLD.content_ref
       OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
       OR NEW.bytes IS DISTINCT FROM OLD.bytes THEN
      RAISE EXCEPTION 'content_reference_binding_immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.tombstoned_at IS NULL THEN
      RAISE EXCEPTION 'content_reference_update_forbidden' USING ERRCODE = '23514';
    END IF;
  ELSIF OLD.slot_state = 'reserved' THEN
    IF NEW.slot_state = 'committed' THEN
      -- The candidate object becomes the committed fact; the content pair is
      -- filled for the first time and no tombstone may race the commit.
      IF NEW.tombstoned_at IS NOT NULL THEN
        RAISE EXCEPTION 'content_reference_update_forbidden' USING ERRCODE = '23514';
      END IF;
    ELSIF NEW.slot_state = 'reserved' THEN
      -- A reserved slot may only be tombstoned; it cannot accumulate partial
      -- content or flip back from committed.
      IF NEW.content_ref IS DISTINCT FROM OLD.content_ref
         OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
         OR NEW.bytes IS DISTINCT FROM OLD.bytes THEN
        RAISE EXCEPTION 'content_reference_binding_immutable' USING ERRCODE = '23514';
      END IF;
      IF NEW.tombstoned_at IS NULL THEN
        RAISE EXCEPTION 'content_reference_update_forbidden' USING ERRCODE = '23514';
      END IF;
    ELSE
      RAISE EXCEPTION 'content_reference_invalid_transition' USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'content_reference_invalid_state' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;

DECLARE
  export_row work.audit_export%ROWTYPE;
  retention int;
  req_hash text;
BEGIN
  PERFORM work.assert_org_admin(p_org_id, p_subject_id);
  IF p_client_request_id IS NULL OR char_length(btrim(p_client_request_id)) < 8
     OR char_length(p_client_request_id) > 128 THEN
    RAISE EXCEPTION 'invalid_request:client_request_id' USING ERRCODE = '22023';
  END IF;
  IF p_format IS NULL OR p_format NOT IN ('csv', 'json') THEN
    RAISE EXCEPTION 'invalid_request:export_format' USING ERRCODE = '22023';
  END IF;
  IF p_range_from IS NULL OR p_range_to IS NULL OR p_range_from >= p_range_to THEN
    RAISE EXCEPTION 'audit_export_range_invalid' USING ERRCODE = 'P0001';
  END IF;
  IF p_range_to > now() THEN
    RAISE EXCEPTION 'audit_export_range_invalid' USING ERRCODE = 'P0001';
  END IF;

  SELECT COALESCE(NULLIF(op.policy->>'audit_retention_days', '')::int, 365)
    INTO retention
  FROM work.org_policy op WHERE op.org_id = p_org_id;
  IF retention IS NULL THEN
    retention := 365;
  END IF;
  IF p_range_from < now() - make_interval(days => retention) THEN
    RAISE EXCEPTION 'audit_export_range_invalid' USING ERRCODE = 'P0001';
  END IF;
  IF p_range_to - p_range_from > make_interval(days => 92) THEN
    RAISE EXCEPTION 'audit_export_range_invalid' USING ERRCODE = 'P0001';
  END IF;

  req_hash := work.sha256_text(jsonb_build_object(
    'client_request_id', p_client_request_id,
    'range_from', p_range_from,
    'range_to', p_range_to,
    'format', p_format
  )::text);

  SELECT * INTO export_row
  FROM work.audit_export e
  WHERE e.org_id = p_org_id AND e.client_request_id = p_client_request_id
  FOR UPDATE;

  IF FOUND THEN
    IF export_row.request_hash <> req_hash THEN
      RAISE EXCEPTION 'idempotency_key_conflict' USING ERRCODE = 'P0001';
    END IF;
    RETURN work.audit_export_view(export_row);
  END IF;

  INSERT INTO work.audit_export
    (org_id, requested_by, client_request_id, request_hash, range_from, range_to, format, status)
  VALUES
    (p_org_id, p_subject_id, p_client_request_id, req_hash, p_range_from, p_range_to, p_format, 'queued')
  RETURNING * INTO export_row;

  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'audit_export.requested', 'audit_export', export_row.id::text,
    jsonb_build_object('format', p_format, 'range_from', p_range_from, 'range_to', p_range_to)
  );
  RETURN work.audit_export_view(export_row);
END;

DECLARE
  input_id uuid;
BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  PERFORM 1 FROM work.member
  WHERE org_id = p_org_id
    AND subject_id = p_subject_id
    AND status = 'active'
    AND work_seat = true
    AND role <> 'viewer';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'work_seat_required' USING ERRCODE = 'P0001';
  END IF;
  IF p_content_ref IS NULL OR p_content_ref = ''
     OR p_content_hash IS NULL OR p_content_hash = ''
     OR p_bytes IS NULL OR p_bytes <= 0
     OR p_media_type IS NULL OR p_media_type = '' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  -- 只复用尚未绑定任务的同哈希输入；已绑定的输入属于那个任务，删除时随之粉碎。
  -- 未绑定输入按 work.input_ttl_hours（默认 24 小时）过期，由 work.expire_due_inputs 清扫。
  INSERT INTO work.input_object
    (org_id, subject_id, purpose, content_ref, content_hash, bytes, media_type, expires_at)
  VALUES
    (p_org_id, p_subject_id, 'task_input', p_content_ref, p_content_hash, p_bytes, p_media_type,
     now() + make_interval(hours => work.input_ttl_hours()))
  ON CONFLICT (org_id, subject_id, content_hash, purpose) WHERE status = 'active' AND task_id IS NULL
  DO NOTHING
  RETURNING id INTO input_id;
  IF input_id IS NULL THEN
    SELECT id INTO input_id
    FROM work.input_object
    WHERE org_id = p_org_id
      AND subject_id = p_subject_id
      AND content_hash = p_content_hash
      AND purpose = 'task_input'
      AND status = 'active'
      AND task_id IS NULL;
  END IF;
  IF input_id IS NULL THEN
    RAISE EXCEPTION 'input_conflict_retry' USING ERRCODE = '40001';
  END IF;
  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'input.create', 'input', input_id::text,
    jsonb_build_object('bytes', p_bytes, 'media_type', p_media_type)
  );
  RETURN input_id;
END;

DECLARE
  dedup_row work.submission_dedup%ROWTYPE;
  req_hash text;
  input_id uuid;
BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  PERFORM work.lock_request_key(
    p_org_id, p_subject_id, 'input.create', p_client_request_id
  );
  req_hash := work.sha256_text(jsonb_build_object(
    'content_hash', p_content_hash,
    'bytes', p_bytes,
    'media_type', p_media_type
  )::text);
  SELECT * INTO dedup_row
  FROM work.submission_dedup d
  WHERE d.org_id = p_org_id
    AND d.subject_id = p_subject_id
    AND d.operation_type = 'input.create'
    AND d.client_request_id = p_client_request_id
  FOR UPDATE;
  IF FOUND THEN
    IF dedup_row.request_hash <> req_hash THEN
      RAISE EXCEPTION 'idempotency_key_conflict' USING ERRCODE = 'P0001';
    END IF;
    RETURN dedup_row.result_ref::uuid;
  END IF;
  input_id := work.create_input(
    p_org_id, p_subject_id, p_content_ref, p_content_hash, p_bytes, p_media_type
  );
  INSERT INTO work.submission_dedup
    (org_id, subject_id, operation_type, client_request_id, request_hash, result_ref)
  VALUES
    (p_org_id, p_subject_id, 'input.create', p_client_request_id, req_hash,
     input_id::text);
  RETURN input_id;
END;

DECLARE
  run_row work.run%ROWTYPE;
  existing work.operation%ROWTYPE;
  operation_id uuid := gen_random_uuid();
BEGIN
  SELECT * INTO run_row FROM work.run WHERE id = p_run_id AND org_id = p_org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM work.task WHERE id = run_row.task_id AND org_id = p_org_id FOR UPDATE;
  SELECT * INTO run_row FROM work.run WHERE id = p_run_id AND org_id = p_org_id FOR UPDATE;
  IF run_row.state NOT IN ('active', 'waiting') THEN
    RAISE EXCEPTION 'run_not_accepting_operations' USING ERRCODE = 'P0001';
  END IF;
  IF p_kind NOT IN ('model', 'tool', 'artifact') THEN
    RAISE EXCEPTION 'scope_unavailable:operation_kind' USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO existing
  FROM work.operation
  WHERE org_id = p_org_id AND run_id = p_run_id AND logical_key = p_logical_key;
  IF FOUND THEN
    IF existing.request_hash <> p_request_hash THEN
      RAISE EXCEPTION 'operation_key_conflict' USING ERRCODE = 'P0001';
    END IF;
    RETURN existing.id;
  END IF;
  INSERT INTO work.operation
    (id, org_id, run_id, logical_key, kind, request_hash, state)
  VALUES
    (operation_id, p_org_id, p_run_id, p_logical_key, p_kind, p_request_hash, 'prepared');
  RETURN operation_id;
END;

DECLARE
  new_id uuid := gen_random_uuid();
BEGIN
  PERFORM work.assert_org_owner(p_org_id, p_subject_id);
  IF p_provider NOT IN ('aliyun', 'volcengine', 'deepseek') THEN
    RAISE EXCEPTION 'invalid_request:provider' USING ERRCODE = '22023';
  END IF;
  IF p_secret_fingerprint IS NULL OR length(btrim(p_secret_fingerprint)) NOT BETWEEN 8 AND 64 THEN
    RAISE EXCEPTION 'invalid_request:fingerprint' USING ERRCODE = '22023';
  END IF;
  IF p_mode = 'managed_key' THEN
    IF p_secret_ciphertext IS NULL OR p_role_ref IS NOT NULL
       OR (p_wrapped_dek IS NULL) <> (p_kms_key_ref IS NULL)
       OR (p_kms_key_ref IS NOT NULL AND length(btrim(p_kms_key_ref)) = 0) THEN
      RAISE EXCEPTION 'invalid_request:credential' USING ERRCODE = '22023';
    END IF;
  ELSIF p_mode = 'sts_role' THEN
    IF p_role_ref IS NULL OR length(btrim(p_role_ref)) = 0
       OR p_secret_ciphertext IS NOT NULL OR p_wrapped_dek IS NOT NULL OR p_kms_key_ref IS NOT NULL THEN
      RAISE EXCEPTION 'invalid_request:credential' USING ERRCODE = '22023';
    END IF;
  ELSE
    RAISE EXCEPTION 'invalid_request:credential_mode' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM work.provider_credential pc
    WHERE pc.org_id = p_org_id AND pc.provider = p_provider AND pc.state = 'active'
  ) THEN
    RAISE EXCEPTION 'provider_credential_exists' USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO work.provider_credential
    (id, org_id, provider, mode, role_ref, secret_ciphertext, wrapped_dek, kms_key_ref,
     secret_fingerprint, created_by)
  VALUES
    (new_id, p_org_id, p_provider, p_mode, p_role_ref, p_secret_ciphertext, p_wrapped_dek,
     p_kms_key_ref, btrim(p_secret_fingerprint), p_subject_id);
  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'provider.credential_created', 'provider_credential', new_id::text,
    jsonb_build_object(
      'provider', p_provider, 'mode', p_mode,
      'fingerprint', btrim(p_secret_fingerprint), 'key_version', 1
    )
  );
  RETURN QUERY SELECT new_id, 1;
END;

DECLARE
  task_row work.task%ROWTYPE;
  artifact_row work.artifact%ROWTYPE;
  dedup_row work.submission_dedup%ROWTYPE;
  v_task_id uuid;
  latest_version int;
  req_hash text;
BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  PERFORM work.lock_request_key(p_org_id, p_subject_id, 'artifact.version', p_client_request_id);
  IF p_base_version_no IS NULL OR p_base_version_no < 1
     OR p_content_ref IS NULL OR p_content_ref = ''
     OR p_content_hash IS NULL OR p_content_hash = ''
     OR p_bytes IS NULL OR p_bytes <= 0
     OR p_media_type IS NULL OR p_media_type = '' THEN
    RAISE EXCEPTION 'invalid_request' USING ERRCODE = '22023';
  END IF;
  req_hash := work.sha256_text(concat_ws(':', p_artifact_id, p_base_version_no, p_content_hash));
  SELECT * INTO dedup_row
  FROM work.submission_dedup d
  WHERE d.org_id = p_org_id AND d.subject_id = p_subject_id
    AND d.operation_type = 'artifact.version' AND d.client_request_id = p_client_request_id;
  IF FOUND THEN
    IF dedup_row.request_hash <> req_hash THEN
      RAISE EXCEPTION 'idempotency_key_conflict' USING ERRCODE = 'P0001';
    END IF;
    IF dedup_row.task_deleted THEN
      RAISE EXCEPTION 'artifact_not_found' USING ERRCODE = 'P0002';
    END IF;
    RETURN QUERY
      SELECT dedup_row.result_ref::int, t.revision
      FROM work.task t WHERE t.id = dedup_row.task_id AND t.org_id = p_org_id;
    RETURN;
  END IF;

  SELECT a.task_id INTO v_task_id FROM work.artifact a WHERE a.id = p_artifact_id AND a.org_id = p_org_id;
  IF v_task_id IS NULL THEN
    RAISE EXCEPTION 'artifact_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO task_row FROM work.task t
  WHERE t.id = v_task_id AND t.org_id = p_org_id AND t.deleted_at IS NULL
  FOR UPDATE;
  SELECT * INTO artifact_row FROM work.artifact a
  WHERE a.id = p_artifact_id AND a.org_id = p_org_id AND a.deleted_at IS NULL
  FOR UPDATE;
  IF task_row.id IS NULL OR artifact_row.id IS NULL OR task_row.owner_subject_id <> p_subject_id THEN
    RAISE EXCEPTION 'artifact_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF task_row.state NOT IN ('open', 'awaiting_acceptance') THEN
    RAISE EXCEPTION 'artifact_read_only' USING ERRCODE = 'P0001';
  END IF;
  IF task_row.active_run_id IS NOT NULL THEN
    RAISE EXCEPTION 'run_not_quiescent' USING ERRCODE = 'P0001';
  END IF;
  -- UI shows run_canceled/failed artifacts as read-only: a terminal, unsuccessful
  -- latest run freezes editing until a later run succeeds.
  IF task_row.latest_run_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM work.run r
    WHERE r.id = task_row.latest_run_id AND r.org_id = p_org_id
      AND r.state IN ('failed', 'canceled')
  ) THEN
    RAISE EXCEPTION 'artifact_read_only' USING ERRCODE = 'P0001';
  END IF;
  SELECT MAX(v.version_no) INTO latest_version
  FROM work.artifact_version v
  WHERE v.artifact_id = p_artifact_id AND v.org_id = p_org_id AND v.state = 'published';
  IF latest_version IS DISTINCT FROM p_base_version_no THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001', DETAIL = COALESCE(latest_version, 0)::text;
  END IF;
  INSERT INTO work.artifact_version
    (artifact_id, org_id, version_no, content_ref, content_hash, bytes, media_type, state, provenance)
  VALUES
    (p_artifact_id, p_org_id, latest_version + 1, p_content_ref, p_content_hash, p_bytes, p_media_type,
     'staged', jsonb_build_object('source', 'user', 'base_version_no', p_base_version_no));
  UPDATE work.artifact_version v
  SET state = 'published', published_at = now()
  WHERE v.artifact_id = p_artifact_id AND v.org_id = p_org_id AND v.version_no = latest_version + 1;
  UPDATE work.artifact a
  SET revision = a.revision + 1, updated_at = now()
  WHERE a.id = p_artifact_id AND a.org_id = p_org_id;
  UPDATE work.task t
  SET revision = t.revision + 1, updated_at = now()
  WHERE t.id = v_task_id AND t.org_id = p_org_id;
  INSERT INTO work.submission_dedup
    (org_id, subject_id, operation_type, client_request_id, request_hash, task_id, result_state, result_ref)
  VALUES
    (p_org_id, p_subject_id, 'artifact.version', p_client_request_id, req_hash, v_task_id, 'published',
     (latest_version + 1)::text);
  PERFORM work.append_task_event(
    p_org_id, v_task_id, 'artifact.published',
    jsonb_build_object('artifact_id', p_artifact_id, 'version_no', latest_version + 1, 'source', 'user',
                       'content_hash', p_content_hash, 'bytes', p_bytes, 'media_type', p_media_type)
  );
  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'artifact.version_create', 'artifact', p_artifact_id::text,
    jsonb_build_object('task_id', v_task_id, 'version_no', latest_version + 1, 'base_version_no', p_base_version_no)
  );
  RETURN QUERY SELECT latest_version + 1, task_row.revision + 1;
END;

DECLARE
  approval_row work.approval%ROWTYPE;
  operation_row work.operation%ROWTYPE;
  task_row work.task%ROWTYPE;
  task_id uuid;
  existing_decision work.approval_decision%ROWTYPE;
  reservation_id uuid;
BEGIN
  PERFORM work.assert_session_subject(p_actor_subject_id);
  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'invalid_approval_decision' USING ERRCODE = '22023';
  END IF;
  SELECT o.id, r.task_id INTO operation_row.id, task_id
  FROM work.approval_operation ao
  JOIN work.operation o ON o.id = ao.operation_id AND o.org_id = ao.org_id
  JOIN work.run r ON r.id = o.run_id AND r.org_id = o.org_id
  WHERE ao.approval_id = p_approval_id AND ao.org_id = p_org_id;
  IF operation_row.id IS NULL THEN
    RAISE EXCEPTION 'approval_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO task_row FROM work.task t WHERE t.id = task_id AND t.org_id = p_org_id FOR UPDATE;
  IF task_row.deleted_at IS NOT NULL
     OR task_row.owner_subject_id <> p_actor_subject_id
     OR NOT EXISTS (
       SELECT 1 FROM work.member m
       WHERE m.org_id = p_org_id AND m.subject_id = p_actor_subject_id
         AND m.status = 'active' AND m.role <> 'viewer'
     ) THEN
    RAISE EXCEPTION 'approval_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO operation_row
  FROM work.operation o
  WHERE o.id = operation_row.id AND o.org_id = p_org_id
  FOR UPDATE;
  SELECT * INTO approval_row
  FROM work.approval a
  WHERE a.id = p_approval_id AND a.org_id = p_org_id
  FOR UPDATE;
  IF approval_row.status <> 'pending' THEN
    SELECT * INTO existing_decision
    FROM work.approval_decision d
    WHERE d.approval_id = p_approval_id AND d.org_id = p_org_id;
    IF FOUND
       AND existing_decision.decision = p_decision
       AND existing_decision.params_hash = p_params_hash
       AND existing_decision.actor_subject_id = p_actor_subject_id THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'approval_not_pending' USING ERRCODE = 'P0001';
  END IF;
  IF approval_row.revision <> p_expected_revision
     OR approval_row.params_hash <> p_params_hash
     OR approval_row.expires_at <= now() THEN
    RAISE EXCEPTION 'approval_stale_or_expired' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.approval a
  SET status = p_decision,
      revision = a.revision + 1,
      updated_at = now()
  WHERE a.id = p_approval_id AND a.org_id = p_org_id;
  INSERT INTO work.approval_decision
    (approval_id, org_id, decision, actor_subject_id, params_hash, policy_epoch)
  VALUES
    (p_approval_id, p_org_id, p_decision, p_actor_subject_id, p_params_hash, approval_row.policy_epoch);
  IF p_decision = 'approved' THEN
    UPDATE work.operation o
    SET state = 'authorized',
        revision = o.revision + 1,
        updated_at = now()
    WHERE o.id = operation_row.id AND o.org_id = p_org_id;
  ELSE
    UPDATE work.operation o
    SET state = 'canceled',
        revision = o.revision + 1,
        updated_at = now()
    WHERE o.id = operation_row.id AND o.org_id = p_org_id;
    SELECT br.id INTO reservation_id
    FROM work.quota_reservation br
    WHERE br.operation_id = operation_row.id AND br.state = 'held';
    IF reservation_id IS NOT NULL THEN
      PERFORM work.release_quota(reservation_id);
    END IF;
  END IF;
  PERFORM work.append_task_event(
    p_org_id, task_id, 'approval.decided',
    jsonb_build_object(
      'approval_id', p_approval_id,
      'operation_id', operation_row.id,
      'decision', p_decision
    )
  );
  PERFORM work.append_audit(
    p_org_id, p_actor_subject_id, 'approval.decide', 'approval', p_approval_id::text,
    jsonb_build_object('operation_id', operation_row.id, 'decision', p_decision)
  );
END;

BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  IF p_expected_revision IS NULL THEN
    RAISE EXCEPTION 'invalid_request' USING ERRCODE = '22023';
  END IF;
  RETURN work.delete_task_core(
    p_org_id, p_task_id, p_subject_id, p_subject_id, p_expected_revision,
    work.reason_code(p_reason), 'task.deleted');
END;

DECLARE
  task_row work.task%ROWTYPE;
  refs jsonb;
  artifact_count int;
BEGIN
  SELECT * INTO task_row
  FROM work.task t
  WHERE t.id = p_task_id AND t.org_id = p_org_id
  FOR UPDATE;
  IF NOT FOUND
     OR (p_required_owner IS NOT NULL AND task_row.owner_subject_id <> p_required_owner) THEN
    RAISE EXCEPTION 'task_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF task_row.deleted_at IS NOT NULL THEN
    RETURN 0;
  END IF;
  IF p_expected_revision IS NOT NULL AND task_row.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001', DETAIL = task_row.revision::text;
  END IF;
  IF task_row.active_run_id IS NOT NULL OR work.task_has_blocking_operation(p_task_id, p_org_id) THEN
    RAISE EXCEPTION 'run_not_quiescent' USING ERRCODE = 'P0001';
  END IF;

  -- 只粉碎不再被其他存活输入/成果引用的正文对象（Content Store 若按内容去重，引用可能共享）。
  SELECT COALESCE(jsonb_agg(DISTINCT s.ref), '[]'::jsonb) INTO refs
  FROM (
    SELECT v.content_ref AS ref
    FROM work.artifact a
    JOIN work.artifact_version v ON v.artifact_id = a.id AND v.org_id = a.org_id
    WHERE a.task_id = p_task_id AND a.org_id = p_org_id
    UNION
    SELECT i.content_ref
    FROM work.input_object i
    WHERE i.id = task_row.input_id AND i.org_id = p_org_id AND i.task_id = p_task_id
  ) s
  WHERE NOT EXISTS (
    SELECT 1 FROM work.input_object i2
    WHERE i2.org_id = p_org_id AND i2.content_ref = s.ref AND i2.deleted_at IS NULL
      AND i2.task_id IS DISTINCT FROM p_task_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM work.artifact_version v2
    JOIN work.artifact a2 ON a2.id = v2.artifact_id AND a2.org_id = v2.org_id
    WHERE v2.org_id = p_org_id AND v2.content_ref = s.ref AND a2.deleted_at IS NULL
      AND a2.task_id <> p_task_id
  );

  INSERT INTO work.artifact_tombstone (artifact_id, org_id)
  SELECT a.id, a.org_id FROM work.artifact a
  WHERE a.task_id = p_task_id AND a.org_id = p_org_id AND a.deleted_at IS NULL
  ON CONFLICT (artifact_id) DO NOTHING;
  UPDATE work.artifact a
  SET state = 'deleted', deleted_at = now(), updated_at = now()
  WHERE a.task_id = p_task_id AND a.org_id = p_org_id AND a.deleted_at IS NULL;
  GET DIAGNOSTICS artifact_count = ROW_COUNT;

  UPDATE work.input_object i
  SET status = 'deleted', deleted_at = now()
  WHERE i.id = task_row.input_id AND i.org_id = p_org_id AND i.task_id = p_task_id
    AND i.deleted_at IS NULL;

  UPDATE work.submission_dedup d
  SET task_deleted = true
  WHERE d.org_id = p_org_id AND d.task_id = p_task_id;

  UPDATE work.task t
  SET deleted_at = now(), title = '[deleted]', revision = t.revision + 1, updated_at = now()
  WHERE t.id = p_task_id AND t.org_id = p_org_id;

  INSERT INTO work.outbox (org_id, aggregate_type, aggregate_id, event_id, payload)
  VALUES (p_org_id, 'content', p_task_id, gen_random_uuid(),
          jsonb_build_object('kind', 'content_shred', 'task_id', p_task_id, 'content_refs', refs));

  PERFORM work.append_audit(
    p_org_id, p_actor_subject_id, p_action, 'task', p_task_id::text,
    jsonb_build_object('reason', p_reason, 'artifacts', artifact_count,
                       'content_refs', jsonb_array_length(refs), 'owner_subject_id', task_row.owner_subject_id)
  );
  RETURN jsonb_array_length(refs);
END;

BEGIN
  IF p_org_id IS NULL OR p_org_id = ''
     OR p_org_id IS DISTINCT FROM current_setting('app.org_id', true) THEN
    RAISE EXCEPTION 'directory_org_context_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF p_max_age_seconds IS NULL OR p_max_age_seconds < 60 OR p_max_age_seconds > 86400 THEN
    RAISE EXCEPTION 'invalid_request:max_age' USING ERRCODE = '22023';
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM work.directory_sync_state s
    WHERE s.org_id = p_org_id
      AND s.last_error IS NULL
      AND s.last_success_at IS NOT NULL
      AND s.last_success_at >= now() - make_interval(secs => p_max_age_seconds)
  );
END;

DECLARE
  current_revision bigint;
BEGIN
  IF p_org_id IS NULL OR p_org_id = ''
     OR p_org_id IS DISTINCT FROM current_setting('app.org_id', true) THEN
    RAISE EXCEPTION 'directory_org_context_mismatch' USING ERRCODE = 'P0001';
  END IF;
  SELECT o.revision INTO current_revision FROM work.org o WHERE o.id = p_org_id;
  RETURN current_revision;
END;

BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
     OR NEW.execution_id IS DISTINCT FROM OLD.execution_id
     OR NEW.holder_id IS DISTINCT FROM OLD.holder_id
     OR NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.receipt_slot_id IS DISTINCT FROM OLD.receipt_slot_id
     OR NEW.consumed_at IS DISTINCT FROM OLD.consumed_at
     OR NEW.sealed_at IS DISTINCT FROM OLD.sealed_at THEN
    RAISE EXCEPTION 'dispatch_gate_binding_immutable' USING ERRCODE = '23514';
  END IF;
  IF OLD.gate_state = 'sealed_not_sent' THEN
    RAISE EXCEPTION 'dispatch_gate_sealed_immutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.gate_state IS DISTINCT FROM OLD.gate_state
     AND NOT (OLD.gate_state = 'consumed' AND NEW.gate_state = 'receipt_recorded') THEN
    RAISE EXCEPTION 'dispatch_gate_state_immutable' USING ERRCODE = '23514';
  END IF;
  IF OLD.gate_state = 'receipt_recorded'
     AND (NEW.receipt_ref IS DISTINCT FROM OLD.receipt_ref
          OR NEW.receipt_hash IS DISTINCT FROM OLD.receipt_hash
          OR NEW.receipt_result IS DISTINCT FROM OLD.receipt_result
          OR NEW.receipt_recorded_at IS DISTINCT FROM OLD.receipt_recorded_at) THEN
    RAISE EXCEPTION 'dispatch_receipt_immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;

BEGIN
  PERFORM work.append_task_event(
    NEW.org_id, NEW.task_id, 'task.completed',
    jsonb_build_object(
      'acceptance_id', NEW.id,
      'basis', CASE WHEN NEW.artifact_id IS NULL THEN 'reason' ELSE 'version' END,
      'artifact_id', NEW.artifact_id,
      'version_no', NEW.version_no
    )
  );
  RETURN NEW;
END;

BEGIN
  IF NEW.state IN ('succeeded', 'failed', 'canceled') AND NEW.state IS DISTINCT FROM OLD.state THEN
    PERFORM work.append_task_event(
      NEW.org_id, NEW.task_id, 'run.' || NEW.state,
      jsonb_build_object('run_id', NEW.id, 'attempt_no', NEW.attempt_no, 'terminal_reason', NEW.terminal_reason)
    );
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.state = 'awaiting_acceptance' AND OLD.state IS DISTINCT FROM 'awaiting_acceptance' THEN
    PERFORM work.append_task_event(
      NEW.org_id, NEW.id, 'task.awaiting_acceptance',
      jsonb_build_object('latest_run_id', NEW.latest_run_id)
    );
  END IF;
  RETURN NEW;
END;

BEGIN
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM work.state_transition
    WHERE entity = 'approval' AND from_state = OLD.status AND to_state = NEW.status
  ) THEN
    RAISE EXCEPTION 'invalid_transition:approval:%->%', OLD.status, NEW.status
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;

BEGIN
  PERFORM 1
  FROM work.run r
  JOIN work.task t ON t.id = r.task_id AND t.org_id = r.org_id
  WHERE r.id = NEW.run_id
    AND r.org_id = NEW.org_id
    AND t.state = 'open'
    AND t.active_run_id = r.id
    AND r.state IN ('active', 'waiting')
  FOR SHARE OF r, t;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'operation_run_not_active' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM work.org
    WHERE id = NEW.org_id
      AND status = 'active'
      AND execution_enabled
      AND NOT operator_suspended
  ) THEN
    RAISE EXCEPTION 'org_execution_unavailable' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;

DECLARE
  entity_name text := TG_ARGV[0];
BEGIN
  IF OLD.state = NEW.state THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM work.state_transition
    WHERE entity = entity_name AND from_state = OLD.state AND to_state = NEW.state
  ) THEN
    RAISE EXCEPTION 'invalid_transition:%:%->%', entity_name, OLD.state, NEW.state
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;

DECLARE
  account_id uuid;
BEGIN
  IF p_org_id IS NULL OR p_org_id = ''
     OR p_org_id IS DISTINCT FROM current_setting('app.org_id', true) THEN
    RAISE EXCEPTION 'org_context_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF p_account_key IS NULL OR p_account_key !~ '^[a-z][a-z0-9_-]{1,31}$'
     OR p_period_id IS NULL OR p_period_id !~ '^[0-9]{4}-[0-9]{2}$' THEN
    RAISE EXCEPTION 'invalid_request:quota_period' USING ERRCODE = '22023';
  END IF;
  IF p_enforcement NOT IN ('soft', 'hard') THEN
    RAISE EXCEPTION 'invalid_request:quota_enforcement' USING ERRCODE = '22023';
  END IF;
  IF p_limit_tokens IS NULL OR p_limit_tokens <= 0 THEN
    RAISE EXCEPTION 'invalid_request:quota_limit' USING ERRCODE = '22023';
  END IF;
  INSERT INTO work.quota_account
    (org_id, account_key, period_id, limit_tokens, enforcement)
  VALUES (p_org_id, p_account_key, p_period_id, p_limit_tokens, p_enforcement)
  ON CONFLICT (org_id, account_key, period_id) DO NOTHING;
  SELECT a.id INTO account_id
  FROM work.quota_account a
  WHERE a.org_id = p_org_id AND a.account_key = p_account_key AND a.period_id = p_period_id;
  IF account_id IS NULL THEN
    RAISE EXCEPTION 'quota_account_not_found' USING ERRCODE = 'P0002';
  END IF;
  RETURN account_id;
END;

DECLARE
  affected int;
BEGIN
  UPDATE work.audit_export e
    SET status = 'expired', expires_at = NULL, updated_at = now()
  WHERE e.status = 'ready' AND e.expires_at <= p_now;
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;

DECLARE
  swept int := 0;
  input_row work.input_object%ROWTYPE;
  shared boolean;
BEGIN
  FOR input_row IN
    SELECT * FROM work.input_object i
    WHERE i.status = 'active'
      AND i.task_id IS NULL
      AND i.expires_at IS NOT NULL
      AND i.expires_at <= p_now
    ORDER BY i.expires_at, i.id
    FOR UPDATE
  LOOP
    UPDATE work.input_object i
      SET status = 'expired', deleted_at = now()
    WHERE i.id = input_row.id;
    swept := swept + 1;

    SELECT EXISTS (
      SELECT 1 FROM work.input_object other
      WHERE other.org_id = input_row.org_id
        AND other.content_ref = input_row.content_ref
        AND other.deleted_at IS NULL
        AND other.id <> input_row.id
    ) OR EXISTS (
      SELECT 1 FROM work.artifact_version v
      JOIN work.artifact a ON a.id = v.artifact_id AND a.org_id = v.org_id
      WHERE v.org_id = input_row.org_id
        AND v.content_ref = input_row.content_ref
        AND a.deleted_at IS NULL
    ) INTO shared;

    IF NOT shared THEN
      INSERT INTO work.outbox
        (org_id, aggregate_type, aggregate_id, event_id, payload)
      VALUES
        (input_row.org_id, 'content', input_row.id, gen_random_uuid(),
         jsonb_build_object('kind', 'content_shred', 'input_id', input_row.id,
                            'content_refs', jsonb_build_array(input_row.content_ref)));
    END IF;
  END LOOP;

  IF swept > 0 THEN
    PERFORM work.append_audit(
      current_setting('app.org_id', true), NULL, 'input.expiry_swept', 'org',
      current_setting('app.org_id', true),
      jsonb_build_object('count', swept, 'ttl_hours', work.input_ttl_hours())
    );
  END IF;
  RETURN swept;
END;

DECLARE
  export_row work.audit_export%ROWTYPE;
BEGIN
  PERFORM work.reason_code(p_error_code);
  SELECT * INTO export_row
  FROM work.audit_export e
  WHERE e.id = p_export_id AND e.org_id = current_setting('app.org_id', true)
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit_export_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF export_row.status <> 'running'
     OR export_row.lease_owner IS DISTINCT FROM p_worker_id
     OR export_row.lease_until <= now() THEN
    RAISE EXCEPTION 'audit_export_lease_lost' USING ERRCODE = 'P0001';
  END IF;

  UPDATE work.audit_export e
    SET status = 'failed',
        error_code = p_error_code,
        lease_owner = NULL,
        lease_until = NULL,
        updated_at = now()
  WHERE e.id = export_row.id
  RETURNING * INTO export_row;

  PERFORM work.append_audit(
    export_row.org_id, NULL, 'audit_export.failed', 'audit_export', export_row.id::text,
    jsonb_build_object('error_code', p_error_code)
  );
  RETURN work.audit_export_view(export_row);
END;

DECLARE
  task_id uuid;
  operation_row work.operation%ROWTYPE;
BEGIN
  IF p_outcome NOT IN ('succeeded', 'failed') THEN
    RAISE EXCEPTION 'invalid_operation_outcome' USING ERRCODE = '22023';
  END IF;
  SELECT r.task_id INTO task_id
  FROM work.operation o
  JOIN work.run r ON r.id = o.run_id AND r.org_id = o.org_id
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF task_id IS NULL THEN
    RAISE EXCEPTION 'operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM work.task t WHERE t.id = task_id AND t.org_id = p_org_id FOR UPDATE;
  SELECT * INTO operation_row
  FROM work.operation o
  WHERE o.id = p_operation_id AND o.org_id = p_org_id
  FOR UPDATE;
  IF operation_row.state = p_outcome
     AND operation_row.provider_request_id IS NOT DISTINCT FROM p_provider_request_id THEN
    RETURN;
  END IF;
  IF operation_row.state <> 'dispatching' THEN
    RAISE EXCEPTION 'operation_not_dispatching' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.operation o
  SET state = p_outcome,
      provider_request_id = p_provider_request_id,
      receipt_ref = p_receipt_ref,
      revision = o.revision + 1,
      updated_at = now()
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  PERFORM work.append_task_event(
    p_org_id, task_id, 'operation.finished',
    jsonb_build_object(
      'operation_id', p_operation_id,
      'outcome', p_outcome,
      'provider_request_id', p_provider_request_id
    )
  );
  PERFORM work.append_audit(
    p_org_id, NULL, 'operation.finish', 'operation', p_operation_id::text,
    jsonb_build_object('outcome', p_outcome, 'provider_request_id', p_provider_request_id)
  );
END;

DECLARE
  operation_row work.operation%ROWTYPE;
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  gate_row work.dispatch_delivery%ROWTYPE;
  fact_row work.operation_usage_fact%ROWTYPE;
  reservation work.quota_reservation%ROWTYPE;
  v_run_id uuid;
  v_subject_id text;
  v_usage_known boolean;
  v_usage_revision int;
  v_usage_note text := 'already_counted';
  v_counted boolean := false;
  v_settled boolean := false;
  v_settlement_tokens bigint;
  v_delta_input bigint;
  v_delta_output bigint;
  v_delta_cached bigint;
  v_outcome text;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  PERFORM work.assert_document_hash('receipt_hash', p_receipt_hash);
  IF p_usage_source IS NULL
     OR p_usage_source NOT IN ('provider', 'gateway_estimate', 'unavailable') THEN
    RAISE EXCEPTION 'invalid_request:usage_source' USING ERRCODE = '22023';
  END IF;
  IF p_provider NOT IN ('aliyun', 'volcengine', 'deepseek') THEN
    RAISE EXCEPTION 'invalid_request:provider' USING ERRCODE = '22023';
  END IF;
  IF p_model IS NULL OR length(btrim(p_model)) = 0 OR p_usage_date IS NULL THEN
    RAISE EXCEPTION 'invalid_request:usage' USING ERRCODE = '22023';
  END IF;
  v_usage_known := p_usage_source IN ('provider', 'gateway_estimate');
  IF v_usage_known THEN
    IF p_input_tokens IS NULL OR p_output_tokens IS NULL OR p_cached_input_tokens IS NULL
       OR p_input_tokens < 0 OR p_output_tokens < 0 OR p_cached_input_tokens < 0 THEN
      RAISE EXCEPTION 'invalid_request:usage_tokens' USING ERRCODE = '22023';
    END IF;
  ELSIF p_input_tokens IS NOT NULL OR p_output_tokens IS NOT NULL
        OR p_cached_input_tokens IS NOT NULL OR p_settlement_tokens IS NOT NULL THEN
    -- unavailable means unknown, never 0.
    RAISE EXCEPTION 'usage_unavailable_requires_null_tokens' USING ERRCODE = '22023';
  END IF;

  SELECT o.run_id INTO v_run_id
  FROM work.operation o
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF v_run_id IS NULL THEN
    RAISE EXCEPTION 'operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  run_row := work.lock_runtime_run(p_org_id, v_run_id);
  SELECT * INTO task_row FROM work.task t WHERE t.id = run_row.task_id AND t.org_id = p_org_id;
  v_subject_id := task_row.owner_subject_id;
  SELECT * INTO operation_row
  FROM work.operation o
  WHERE o.id = p_operation_id AND o.org_id = p_org_id
  FOR UPDATE;
  SELECT * INTO gate_row
  FROM work.dispatch_delivery d
  WHERE d.org_id = p_org_id AND d.operation_id = p_operation_id
  FOR UPDATE;

  IF gate_row.operation_id IS NULL THEN
    RAISE EXCEPTION 'dispatch_gate_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF gate_row.gate_state <> 'receipt_recorded' THEN
    RAISE EXCEPTION 'dispatch_receipt_not_bound' USING ERRCODE = 'P0001',
      DETAIL = gate_row.gate_state;
  END IF;
  IF gate_row.receipt_hash IS DISTINCT FROM p_receipt_hash THEN
    RAISE EXCEPTION 'receipt_hash_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF gate_row.receipt_result <> 'success' THEN
    RAISE EXCEPTION 'receipt_not_successful' USING ERRCODE = 'P0001',
      DETAIL = gate_row.receipt_result;
  END IF;

  -- Usage first: the ledger must never be asked whether usage was counted.
  SELECT * INTO fact_row
  FROM work.operation_usage_fact f
  WHERE f.org_id = p_org_id AND f.operation_id = p_operation_id
  ORDER BY f.usage_revision DESC
  LIMIT 1;
  IF fact_row.id IS NULL THEN
    v_usage_revision := 1;
    INSERT INTO work.operation_usage_fact
      (org_id, operation_id, usage_revision, origin, usage_source, source_receipt_hash,
       subject_id, provider, model, usage_date, input_tokens, output_tokens,
       cached_input_tokens, counted_in_usage_daily)
    VALUES
      (p_org_id, p_operation_id, 1, 'command', p_usage_source, p_receipt_hash,
       v_subject_id, p_provider, btrim(p_model), p_usage_date,
       p_input_tokens, p_output_tokens, p_cached_input_tokens, v_usage_known);
    IF v_usage_known THEN
      PERFORM work.accumulate_usage_daily(
        p_org_id, v_subject_id, p_provider, p_model, p_usage_date,
        p_input_tokens, p_output_tokens, p_cached_input_tokens, 1
      );
      v_counted := true;
      v_usage_note := 'recorded';
    ELSE
      v_usage_note := 'unavailable_pending_reconciliation';
    END IF;
    UPDATE work.operation o
    SET usage_recorded_at = COALESCE(o.usage_recorded_at, now()), updated_at = now()
    WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  ELSIF fact_row.origin = 'legacy_marker_backfill' OR fact_row.source_receipt_hash IS NULL THEN
    -- Counted before this migration (or by the legacy gateway path): a replay
    -- must not add a second contribution to usage_daily.
    v_usage_revision := fact_row.usage_revision;
    v_usage_note := 'legacy_counted';
  ELSIF fact_row.source_receipt_hash IS DISTINCT FROM p_receipt_hash THEN
    RAISE EXCEPTION 'usage_receipt_conflict' USING ERRCODE = 'P0001';
  ELSIF fact_row.usage_source = p_usage_source
        AND fact_row.input_tokens IS NOT DISTINCT FROM p_input_tokens
        AND fact_row.output_tokens IS NOT DISTINCT FROM p_output_tokens
        AND fact_row.cached_input_tokens IS NOT DISTINCT FROM p_cached_input_tokens THEN
    v_usage_revision := fact_row.usage_revision;
    v_usage_note := 'already_counted';
  ELSIF NOT v_usage_known THEN
    RAISE EXCEPTION 'usage_source_downgrade' USING ERRCODE = 'P0001';
  ELSE
    -- Versioned correction: a new revision applies only the difference.
    v_usage_revision := fact_row.usage_revision + 1;
    v_delta_input := p_input_tokens - COALESCE(fact_row.input_tokens, 0);
    v_delta_output := p_output_tokens - COALESCE(fact_row.output_tokens, 0);
    v_delta_cached := p_cached_input_tokens - COALESCE(fact_row.cached_input_tokens, 0);
    INSERT INTO work.operation_usage_fact
      (org_id, operation_id, usage_revision, origin, usage_source, source_receipt_hash,
       subject_id, provider, model, usage_date, input_tokens, output_tokens,
       cached_input_tokens, counted_in_usage_daily)
    VALUES
      (p_org_id, p_operation_id, v_usage_revision, 'command', p_usage_source, p_receipt_hash,
       v_subject_id, p_provider, btrim(p_model), p_usage_date,
       p_input_tokens, p_output_tokens, p_cached_input_tokens, true);
    PERFORM work.accumulate_usage_daily(
      p_org_id, v_subject_id, p_provider, p_model, p_usage_date,
      v_delta_input, v_delta_output, v_delta_cached,
      CASE WHEN fact_row.counted_in_usage_daily THEN 0 ELSE 1 END
    );
    v_counted := true;
    v_usage_note := 'revised';
  END IF;

  -- Confirm the Operation. A confirmed success is only ever recovered forward.
  IF operation_row.state = 'dispatching' THEN
    PERFORM work.finish_operation(
      p_org_id, p_operation_id, 'succeeded',
      gate_row.provider_request_id, gate_row.receipt_ref
    );
    v_outcome := 'confirmed';
  ELSIF operation_row.state IN ('unknown', 'unresolved') THEN
    IF NOT v_usage_known THEN
      RAISE EXCEPTION 'usage_required_for_reconcile' USING ERRCODE = 'P0001';
    END IF;
    v_settlement_tokens := COALESCE(p_settlement_tokens, p_input_tokens + p_output_tokens);
    PERFORM work.reconcile_operation(
      p_org_id, p_operation_id, 'sent_succeeded',
      gate_row.provider_request_id, v_settlement_tokens, gate_row.receipt_ref
    );
    v_settled := true;
    v_outcome := 'confirmed';
  ELSIF operation_row.state IN ('succeeded', 'reconciled') THEN
    v_outcome := 'already_confirmed';
  ELSE
    RAISE EXCEPTION 'operation_not_confirmable' USING ERRCODE = 'P0001',
      DETAIL = operation_row.state;
  END IF;

  -- Settlement recovery: held/unknown reservations settle once usage is known.
  IF NOT v_settled AND v_usage_known THEN
    SELECT * INTO reservation
    FROM work.quota_reservation br
    WHERE br.org_id = p_org_id AND br.operation_id = p_operation_id
    ORDER BY br.reservation_seq DESC
    LIMIT 1
    FOR UPDATE;
    IF reservation.id IS NOT NULL AND reservation.state IN ('held', 'unknown') THEN
      v_settlement_tokens := COALESCE(p_settlement_tokens, p_input_tokens + p_output_tokens);
      PERFORM work.settle_quota(
        reservation.id, v_settlement_tokens,
        jsonb_build_object(
          'resolution', 'receipt_confirmed',
          'receipt_hash', p_receipt_hash,
          'usage_source', p_usage_source,
          'usage_revision', v_usage_revision
        ),
        reservation.settlement_revision + 1
      );
      v_settled := true;
    END IF;
  END IF;

  PERFORM work.append_audit(
    p_org_id, NULL, 'operation.finish_from_receipt', 'operation', p_operation_id::text,
    jsonb_build_object(
      'outcome', v_outcome,
      'receipt_hash', p_receipt_hash,
      'usage_source', p_usage_source,
      'usage_revision', v_usage_revision,
      'usage', v_usage_note,
      'settled', v_settled
    )
  );
  RETURN jsonb_build_object(
    'outcome', v_outcome,
    'usage', v_usage_note,
    'usage_revision', v_usage_revision,
    'usage_counted', v_counted,
    'settled', v_settled
  );
END;

DECLARE
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  v_task_id uuid;
  reason text := work.reason_code(p_reason);
BEGIN
  IF p_outcome NOT IN ('succeeded', 'failed', 'canceled') THEN
    RAISE EXCEPTION 'invalid_run_outcome' USING ERRCODE = '22023';
  END IF;
  SELECT r.task_id INTO v_task_id FROM work.run r
  WHERE r.id = p_run_id AND r.org_id = p_org_id;
  IF v_task_id IS NULL THEN
    RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO task_row FROM work.task t
  WHERE t.id = v_task_id AND t.org_id = p_org_id FOR UPDATE;
  SELECT * INTO run_row FROM work.run r
  WHERE r.id = p_run_id AND r.org_id = p_org_id FOR UPDATE;
  IF run_row.state = p_outcome THEN
    RETURN;
  END IF;
  -- 取消请求已落库后不得再以成功收尾（迟到结果只结算、不发布）。
  IF p_outcome = 'succeeded' AND run_row.state = 'cancel_requested' THEN
    RAISE EXCEPTION 'run_cancel_requested' USING ERRCODE = 'P0001';
  END IF;
  IF task_row.state <> 'open' OR task_row.active_run_id IS DISTINCT FROM p_run_id THEN
    RAISE EXCEPTION 'run_not_current' USING ERRCODE = 'P0001';
  END IF;
  IF p_outcome = 'succeeded' AND work.task_has_blocking_operation(v_task_id, p_org_id) THEN
    RAISE EXCEPTION 'run_has_unresolved_operation' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.run r
  SET state = p_outcome,
      wait_reason = NULL,
      terminal_reason = reason,
      control_revision = r.control_revision + 1,
      updated_at = now()
  WHERE r.id = p_run_id AND r.org_id = p_org_id;
  UPDATE work.task t
  SET state = CASE WHEN p_outcome = 'succeeded' THEN 'awaiting_acceptance' ELSE t.state END,
      active_run_id = NULL,
      latest_run_id = p_run_id,
      revision = t.revision + 1,
      updated_at = now()
  WHERE t.id = v_task_id AND t.org_id = p_org_id;
END;

DECLARE
  export_row work.audit_export%ROWTYPE;
BEGIN
  PERFORM work.assert_org_admin(p_org_id, p_subject_id);
  SELECT * INTO export_row
  FROM work.audit_export e
  WHERE e.id = p_export_id AND e.org_id = p_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit_export_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF export_row.status = 'ready' AND export_row.expires_at <= now() THEN
    UPDATE work.audit_export e
      SET status = 'expired', expires_at = NULL, updated_at = now()
    WHERE e.id = export_row.id
    RETURNING * INTO export_row;
    PERFORM work.append_audit(
      p_org_id, NULL, 'audit_export.expired', 'audit_export', export_row.id::text, '{}'::jsonb
    );
  END IF;
  RETURN work.audit_export_view(export_row);
END;

BEGIN
  PERFORM work.assert_org_admin(p_org_id, p_subject_id);
  IF p_to < p_from OR p_to - p_from > 366 THEN
    RAISE EXCEPTION 'invalid_request:usage_range' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
    SELECT u.provider, u.model,
           sum(u.input_tokens)::bigint, sum(u.output_tokens)::bigint,
           sum(u.cached_input_tokens)::bigint, sum(u.run_count)::bigint
    FROM work.usage_daily u
    WHERE u.org_id = p_org_id AND u.usage_date BETWEEN p_from AND p_to
    GROUP BY u.provider, u.model
    ORDER BY u.provider, u.model;
END;

BEGIN
  PERFORM work.assert_org_owner(p_org_id, p_subject_id);
  RETURN QUERY SELECT c.id, c.revision, c.provider, c.model, c.region, c.endpoint,
                      c.credential_mode, c.credential_id, pc.secret_fingerprint,
                      c.state, c.created_by, c.created_at
  FROM work.provider_access_config c
  JOIN work.provider_credential pc ON pc.id = c.credential_id
  WHERE c.org_id = p_org_id AND c.state = 'active';
END;

BEGIN
  PERFORM work.assert_org_owner(p_org_id, p_subject_id);
  RETURN QUERY
  SELECT pc.id, pc.provider, pc.mode, pc.secret_fingerprint, pc.key_version,
         pc.state, pc.created_at, pc.rotated_at
  FROM work.provider_credential pc
  WHERE pc.org_id = p_org_id AND pc.id = p_credential_id;
END;

BEGIN
  PERFORM work.assert_session_subject(p_subject_id);
  IF p_to < p_from OR p_to - p_from > 366 THEN
    RAISE EXCEPTION 'invalid_request:usage_range' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
    SELECT u.provider, u.model, u.usage_date, u.input_tokens, u.output_tokens,
           u.cached_input_tokens, u.run_count
    FROM work.usage_daily u
    WHERE u.org_id = p_org_id AND u.subject_id = p_subject_id
      AND u.usage_date BETWEEN p_from AND p_to
    ORDER BY u.usage_date, u.provider, u.model;
END;

DECLARE
  export_row work.audit_export%ROWTYPE;
BEGIN
  PERFORM work.assert_org_admin(p_org_id, p_subject_id);
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid_request:token_hash' USING ERRCODE = '22023';
  END IF;
  IF p_ttl_seconds IS NULL OR p_ttl_seconds < 60 OR p_ttl_seconds > 900 THEN
    RAISE EXCEPTION 'invalid_request:ttl_seconds' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO export_row
  FROM work.audit_export e
  WHERE e.id = p_export_id AND e.org_id = p_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit_export_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF export_row.status = 'expired' THEN
    RAISE EXCEPTION 'audit_export_expired' USING ERRCODE = 'P0001';
  END IF;
  IF export_row.status <> 'ready' THEN
    RAISE EXCEPTION 'audit_export_not_ready' USING ERRCODE = 'P0001';
  END IF;
  IF export_row.expires_at <= now() THEN
    RAISE EXCEPTION 'audit_export_expired' USING ERRCODE = 'P0001';
  END IF;
  IF export_row.downloaded_at IS NOT NULL THEN
    RAISE EXCEPTION 'audit_export_already_downloaded' USING ERRCODE = 'P0001';
  END IF;

  -- 下载令牌有效期不得超过文件留存截止时间（P1-2）。
  UPDATE work.audit_export e
    SET download_token_hash = p_token_hash,
        download_expires_at = LEAST(
          now() + make_interval(secs => p_ttl_seconds),
          export_row.expires_at
        ),
        updated_at = now()
  WHERE e.id = export_row.id;

  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'audit_export.ticket_issued', 'audit_export', export_row.id::text,
    jsonb_build_object('expires_at', LEAST(
      now() + make_interval(secs => p_ttl_seconds),
      export_row.expires_at
    ))
  );
  RETURN jsonb_build_object(
    'export_id', export_row.id,
    'expires_at', LEAST(
      now() + make_interval(secs => p_ttl_seconds),
      export_row.expires_at
    ),
    'bytes', export_row.bytes,
    'row_count', export_row.row_count,
    'format', export_row.format
  );
END;

DECLARE
  execution_row work.runtime_execution%ROWTYPE;
  run_row work.run%ROWTYPE;
  task_row work.task%ROWTYPE;
  latest work.runtime_capability%ROWTYPE;
  v_credential_id uuid;
  v_now timestamptz;
  v_expires timestamptz;
  v_generation int;
BEGIN
  PERFORM work.assert_runtime_context(p_org_id);
  PERFORM work.assert_runtime_identifier('holder_id', p_holder_id);
  IF p_execution_id IS NULL THEN
    RAISE EXCEPTION 'invalid_request:execution_id' USING ERRCODE = '22023';
  END IF;
  IF p_audience IS NULL OR p_audience NOT IN ('work-content', 'work-egress') THEN
    RAISE EXCEPTION 'invalid_request:audience' USING ERRCODE = '22023';
  END IF;
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid_request:token_hash' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'runtime_execution_not_found' USING ERRCODE = 'P0002';
  END IF;
  -- Unified lock order: Task -> Run -> runtime_execution -> capability.
  run_row := work.lock_runtime_run(p_org_id, execution_row.run_id);
  SELECT * INTO task_row FROM work.task t WHERE t.id = run_row.task_id AND t.org_id = p_org_id;
  SELECT * INTO execution_row
  FROM work.runtime_execution e
  WHERE e.execution_id = p_execution_id AND e.org_id = p_org_id
  FOR UPDATE;
  v_now := clock_timestamp();

  IF execution_row.state <> 'active' THEN
    RAISE EXCEPTION 'runtime_capability_not_issuable' USING ERRCODE = 'P0001',
      DETAIL = execution_row.state;
  END IF;
  IF execution_row.holder_id IS DISTINCT FROM p_holder_id THEN
    RAISE EXCEPTION 'runtime_execution_holder_mismatch' USING ERRCODE = '42501';
  END IF;
  IF execution_row.lease_until <= v_now OR execution_row.hard_deadline <= v_now THEN
    -- Refuse only; the expiry is committed by renew/register.
    RAISE EXCEPTION 'runtime_execution_expired' USING ERRCODE = 'P0001';
  END IF;
  -- The content audience is the only one a plan fragment may hold; the model
  -- egress audience exists only for an execute fragment bound to an
  -- operation/attempt/request hash (D4 §6.2 item 2).
  IF (execution_row.mode = 'plan' AND p_audience <> 'work-content')
     OR (execution_row.mode = 'execute' AND p_audience <> 'work-egress') THEN
    RAISE EXCEPTION 'runtime_capability_audience_not_allowed' USING ERRCODE = 'P0001',
      DETAIL = execution_row.mode;
  END IF;
  PERFORM work.assert_org_execution_enabled(p_org_id);
  IF task_row.state <> 'open' OR task_row.active_run_id IS DISTINCT FROM run_row.id
     OR run_row.state <> 'active' OR run_row.fence <> execution_row.run_fence THEN
    RAISE EXCEPTION 'run_not_current' USING ERRCODE = 'P0001';
  END IF;
  IF p_expires_at IS NULL OR p_expires_at <= v_now
     OR p_expires_at > v_now + make_interval(secs => work.runtime_capability_max_seconds()) THEN
    RAISE EXCEPTION 'invalid_request:expires_at' USING ERRCODE = '22023';
  END IF;
  -- Token TTL = min(requested, lease_until, hard_deadline): issuance never
  -- extends the lease and never outlives the fragment.
  v_expires := LEAST(p_expires_at, execution_row.lease_until, execution_row.hard_deadline);

  SELECT * INTO latest
  FROM work.runtime_capability c
  WHERE c.org_id = p_org_id AND c.execution_id = p_execution_id
    AND c.audience = p_audience
  ORDER BY c.generation DESC
  LIMIT 1
  FOR UPDATE;

  IF latest.credential_id IS NOT NULL THEN
    IF latest.token_hash = p_token_hash THEN
      -- Same-generation replay of the same digest. A revoked or expired
      -- generation is never revived by a retry.
      IF latest.revoked_at IS NOT NULL OR latest.expires_at <= v_now THEN
        RAISE EXCEPTION 'runtime_capability_conflict' USING ERRCODE = 'P0001';
      END IF;
      RETURN latest.generation;
    END IF;
    v_generation := latest.generation + 1;
  ELSE
    v_generation := 1;
  END IF;

  -- A digest may only ever belong to one issued capability. Anything left here
  -- is a reuse of an older, revoked or foreign digest, which conflicts instead
  -- of minting a new generation.
  IF EXISTS (
    SELECT 1 FROM work.runtime_capability c
    WHERE c.token_hash = p_token_hash
  ) THEN
    RAISE EXCEPTION 'runtime_capability_token_conflict' USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    INSERT INTO work.runtime_capability
      (org_id, execution_id, holder_id, audience, generation, token_hash,
       issued_at, expires_at)
    VALUES
      (p_org_id, p_execution_id, p_holder_id, p_audience, v_generation,
       p_token_hash, v_now, v_expires)
    RETURNING credential_id INTO v_credential_id;
  EXCEPTION WHEN unique_violation THEN
    -- Another issuer claimed this generation with a different digest. Never
    -- silently turn that into the next generation.
    RAISE EXCEPTION 'runtime_capability_generation_conflict' USING ERRCODE = 'P0001';
  END;

  PERFORM work.append_audit(
    p_org_id, NULL, 'runtime.capability_issued', 'runtime_execution', p_execution_id::text,
    jsonb_build_object(
      'credential_id', v_credential_id, 'audience', p_audience,
      'generation', v_generation, 'holder_id', p_holder_id,
      'expires_at', v_expires
    )
  );
  RETURN v_generation;
END;

BEGIN
  RETURN QUERY
  SELECT e.id FROM work.audit_export e
  WHERE e.org_id = p_org_id AND e.status = 'queued'
  ORDER BY e.created_at;
END;

BEGIN
  PERFORM work.assert_org_admin(p_org_id, p_subject_id);
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'invalid_pagination' USING ERRCODE = '22023';
  END IF;
  IF p_cursor IS NOT NULL AND p_cursor = '' THEN
    RAISE EXCEPTION 'invalid_pagination' USING ERRCODE = '22023';
  END IF;

  PERFORM work.append_audit(
    p_org_id, p_subject_id, 'admin.seats_read', 'org', p_org_id,
    jsonb_build_object('limit', p_limit, 'has_cursor', p_cursor IS NOT NULL)
  );

  RETURN QUERY
  SELECT m.subject_id, m.role, m.work_seat, m.status, m.revision
  FROM work.member m
  WHERE m.org_id = p_org_id
    AND m.status <> 'left'
    AND (p_cursor IS NULL OR m.subject_id > p_cursor)
  ORDER BY m.subject_id
  LIMIT p_limit;
END;

DECLARE
  row_ work.outbox%ROWTYPE;
BEGIN
  PERFORM set_config('app.outbox_relay', 'on', true);
  SELECT * INTO row_ FROM work.outbox o WHERE o.event_id = p_event_id FOR UPDATE;
  PERFORM set_config('app.outbox_relay', 'off', true);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'outbox_event_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF row_.delivered_at IS NULL AND row_.dead_lettered_at IS NULL
     AND row_.claimed_by IS DISTINCT FROM p_relay_id THEN
    RAISE EXCEPTION 'outbox_lease_lost' USING ERRCODE = 'P0001';
  END IF;
  RETURN row_;
END;

BEGIN
  IF p_client_request_id IS NULL OR length(p_client_request_id) NOT BETWEEN 8 AND 128 THEN
    RAISE EXCEPTION 'invalid_client_request_id' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    p_org_id || ':' || p_subject_id || ':' || p_operation_type || ':' || p_client_request_id, 0));
END;

DECLARE
  v_task_id uuid;
  run_row work.run%ROWTYPE;
BEGIN
  SELECT r.task_id INTO v_task_id
  FROM work.run r
  WHERE r.id = p_run_id AND r.org_id = p_org_id;
  IF v_task_id IS NULL THEN
    RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM work.task t
  WHERE t.id = v_task_id AND t.org_id = p_org_id
  FOR UPDATE;
  SELECT * INTO run_row
  FROM work.run r
  WHERE r.id = p_run_id AND r.org_id = p_org_id
  FOR UPDATE;
  RETURN run_row;
END;

DECLARE
  member_row work.member%ROWTYPE;
  current_revision bigint;
  total_members integer;
  absent_count integer;
  threshold integer;
  affected integer := 0;
BEGIN
  IF p_org_id IS NULL OR p_org_id = ''
     OR p_org_id IS DISTINCT FROM current_setting('app.org_id', true) THEN
    RAISE EXCEPTION 'directory_org_context_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF p_present_subjects IS NULL THEN
    RAISE EXCEPTION 'invalid_request:present_subjects' USING ERRCODE = '22023';
  END IF;
  IF p_allow_mass_absence IS NULL THEN
    RAISE EXCEPTION 'invalid_request:mass_absence' USING ERRCODE = '22023';
  END IF;
  IF p_snapshot_revision IS NULL OR p_snapshot_revision < 1 THEN
    RAISE EXCEPTION 'invalid_request:snapshot_revision' USING ERRCODE = '22023';
  END IF;
  IF array_length(p_present_subjects, 1) > 10000 THEN
    RAISE EXCEPTION 'invalid_request:present_subjects' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(p_present_subjects) AS subject
    WHERE subject IS NULL OR subject !~ '^[A-Za-z0-9_.:@-]{1,128}$'
  ) THEN
    RAISE EXCEPTION 'invalid_request:subject_id' USING ERRCODE = '22023';
  END IF;

  SELECT o.revision INTO current_revision
  FROM work.org o
  WHERE o.id = p_org_id
  FOR UPDATE;
  IF current_revision IS NULL THEN
    RAISE EXCEPTION 'directory_org_missing' USING ERRCODE = 'P0001';
  END IF;
  IF p_snapshot_revision > current_revision THEN
    RAISE EXCEPTION 'directory_snapshot_ahead' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*) INTO total_members
  FROM work.member
  WHERE org_id = p_org_id
    AND status <> 'left'
    AND revision < p_snapshot_revision;
  SELECT count(*) INTO absent_count
  FROM work.member
  WHERE org_id = p_org_id
    AND status <> 'left'
    AND revision < p_snapshot_revision
    AND NOT (subject_id = ANY (p_present_subjects));
  threshold := GREATEST(10, CEIL(total_members * 0.20)::integer);

  IF NOT p_allow_mass_absence AND absent_count >= threshold THEN
    PERFORM work.append_audit(
      p_org_id, NULL, 'directory.member_absence_blocked', 'org', p_org_id,
      jsonb_build_object(
        'revision', p_snapshot_revision,
        'current_revision', current_revision,
        'absent', absent_count,
        'total', total_members,
        'threshold', threshold,
        'allow_mass_absence', false
      )
    );
    RETURN -1;
  END IF;
  IF absent_count = 0 THEN
    RETURN 0;
  END IF;

  FOR member_row IN
    SELECT * FROM work.member
    WHERE org_id = p_org_id
      AND status <> 'left'
      AND revision < p_snapshot_revision
      AND NOT (subject_id = ANY (p_present_subjects))
    ORDER BY subject_id
    FOR UPDATE
  LOOP
    UPDATE work.member
    SET status = 'left',
        work_seat = false,
        revision = p_snapshot_revision,
        updated_at = now()
    WHERE id = member_row.id;
    PERFORM work.append_audit(
      p_org_id, NULL, 'directory.member_absent', 'member', member_row.subject_id,
      jsonb_build_object(
        'revision', p_snapshot_revision,
        'current_revision', current_revision,
        'previous_status', member_row.status,
        'work_seat_revoked', member_row.work_seat,
        'entitlement_lost', member_row.status = 'active' OR member_row.work_seat
      )
    );
    affected := affected + 1;
  END LOOP;

  PERFORM work.append_audit(
    p_org_id, NULL, 'directory.member_absence_applied', 'org', p_org_id,
    jsonb_build_object(
      'revision', p_snapshot_revision,
      'current_revision', current_revision,
      'absent', affected,
      'total', total_members,
      'threshold', threshold,
      'allow_mass_absence', p_allow_mass_absence
    )
  );
  RETURN affected;
END;

DECLARE
  task_id uuid;
  operation_row work.operation%ROWTYPE;
  reason text := work.reason_code(p_reason);
BEGIN
  SELECT r.task_id INTO task_id
  FROM work.operation o
  JOIN work.run r ON r.id = o.run_id AND r.org_id = o.org_id
  WHERE o.id = p_operation_id AND o.org_id = p_org_id;
  IF task_id IS NULL THEN
    RAISE EXCEPTION 'operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM work.task
  WHERE id = task_id AND org_id = p_org_id
  FOR UPDATE;
  SELECT * INTO operation_row
  FROM work.operation
  WHERE id = p_operation_id AND org_id = p_org_id
  FOR UPDATE;
  IF operation_row.state = 'unknown' THEN
    RETURN;
  END IF;
  IF operation_row.state <> 'dispatching' THEN
    RAISE EXCEPTION 'operation_not_dispatching' USING ERRCODE = 'P0001';
  END IF;
  UPDATE work.operation
  SET state = 'unknown',
      revision = revision + 1,
      updated_at = now()
  WHERE id = p_operation_id AND org_id = p_org_id;
  PERFORM work.append_task_event(
    p_org_id, task_id, 'operation.unknown',
    jsonb_build_object('operation_id', p_operation_id, 'reason', reason)
  );
  PERFORM work.append_audit(
    p_org_id, NULL, 'operation.unknown', 'operation', p_operation_id::text,
    jsonb_build_object('task_id', task_id, 'reason', reason)
  );
END;

DECLARE
  row_ work.outbox%ROWTYPE;
BEGIN
  row_ := work.lock_claimed_outbox(p_event_id, p_relay_id);
  IF row_.delivered_at IS NOT NULL THEN
    RETURN;
  END IF;
  IF row_.dead_lettered_at IS NOT NULL THEN
    RAISE EXCEPTION 'outbox_dead_lettered' USING ERRCODE = 'P0001';
  END IF;
  PERFORM set_config('app.outbox_relay', 'on', true);
  UPDATE work.outbox o
  SET delivered_at = now(), attempts = o.attempts + 1, claimed_until = NULL
  WHERE o.id = row_.id;
  PERFORM set_config('app.outbox_relay', 'off', true);
END;

DECLARE
  row_ work.outbox%ROWTYPE;
  next_attempts int;
  prev_org text := current_setting('app.org_id', true);
BEGIN
  IF p_error_code IS NULL OR p_error_code !~ '^[a-z][a-z0-9_]{1,63}$' THEN
    RAISE EXCEPTION 'invalid_request' USING ERRCODE = '22023';
  END IF;
  row_ := work.lock_claimed_outbox(p_event_id, p_relay_id);
  IF row_.delivered_at IS NOT NULL THEN
    RETURN 'delivered';
  END IF;
  IF row_.dead_lettered_at IS NOT NULL THEN
    RETURN 'dead_letter';
  END IF;
  next_attempts := row_.attempts + 1;
  PERFORM set_config('app.org_id', row_.org_id, true);
  IF NOT p_retryable OR next_attempts >= 10 THEN
    UPDATE work.outbox o
    SET attempts = next_attempts, last_error_code = p_error_code,
        dead_lettered_at = now(), claimed_until = NULL
    WHERE o.id = row_.id;
    PERFORM work.append_audit(
      row_.org_id, 'system:outbox-relay', 'outbox.dead_lettered', row_.aggregate_type,
      row_.aggregate_id::text,
      jsonb_build_object('event_id', p_event_id, 'attempts', next_attempts, 'error_code', p_error_code)
    );
    IF row_.aggregate_type = 'run' AND row_.payload->>'kind' = 'start_workflow' AND EXISTS (
      SELECT 1 FROM work.run r WHERE r.id = row_.aggregate_id AND r.org_id = row_.org_id
        AND r.state IN ('queued', 'cancel_requested')
    ) THEN
      PERFORM work.finish_run(
        row_.aggregate_id, row_.org_id,
        CASE WHEN (SELECT r.state FROM work.run r WHERE r.id = row_.aggregate_id) = 'queued'
             THEN 'failed' ELSE 'canceled' END,
        'dispatch_dead_letter');
      UPDATE work.outbox o
      SET delivered_at = now(), last_error_code = 'superseded_run_terminal', claimed_until = NULL
      WHERE o.aggregate_type = 'run' AND o.aggregate_id = row_.aggregate_id
        AND o.outbox_seq > row_.outbox_seq AND o.delivered_at IS NULL;
    END IF;
    PERFORM set_config('app.org_id', COALESCE(prev_org, ''), true);
    RETURN 'dead_letter';
  END IF;
  UPDATE work.outbox o
  SET attempts = next_attempts,
      last_error_code = p_error_code,
      claimed_until = NULL,
      available_at = now() + make_interval(secs => LEAST(power(2, next_attempts), 300))
  WHERE o.id = row_.id;
  PERFORM set_config('app.org_id', COALESCE(prev_org, ''), true);
  RETURN 'retry_scheduled';
END;

DECLARE
  run_row work.run%ROWTYPE;
  reason text;
BEGIN
  PERFORM work.assert_session_subject(p_actor_subject_id);
  IF p_ticket_ref IS NULL OR p_ticket_ref !~ '^[A-Z][A-Z0-9]+-[0-9]+$' OR length(btrim(coalesce(p_reason, ''))) < 4 THEN
    RAISE EXCEPTION 'invalid_request' USING ERRCODE = '22023';
  END IF;
  reason := work.reason_code(p_reason);
  SELECT * INTO run_row
  FROM work.run r
  WHERE r.id = p_run_id AND r.org_id = p_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF run_row.state IN ('succeeded', 'failed', 'canceled', 'cancel_requested') THEN
    RETURN;
  END IF;
  UPDATE work.run r
  SET state = 'cancel_requested',
      wait_reason = NULL,
      control_revision = r.control_revision + 1,
      updated_at = now()
  WHERE r.id = p_run_id AND r.org_id = p_org_id;
  PERFORM work.append_task_event(
    p_org_id, run_row.task_id, 'run.cancel_requested',
    jsonb_build_object('run_id', p_run_id, 'reason', reason, 'requested_by', 'ops')
  );
  INSERT INTO work.outbox (org_id, aggregate_type, aggregate_id, event_id, payload)
  VALUES (
    p_org_id, 'run', p_run_id, gen_random_uuid(),
    jsonb_build_object('kind', 'cancel_signal', 'run_id', p_run_id, 'reason', reason)
  );
  PERFORM work.append_audit(
    p_org_id, p_actor_subject_id, 'run.cancel_requested_by_ops', 'run', p_run_id::text,
    jsonb_build_object('task_id', run_row.task_id, 'previous_state', run_row.state,
                       'ticket_ref', p_ticket_ref, 'reason', reason)
  );
END;

